  todo_app_task_id String @db.Uuid

  /// Reference to {@link todo_app_users.id} of the user who completed the task
  todo_app_user_id String @db.Uuid

  /// Timestamp when the task was marked complete
  completed_at DateTime @db.Timestamptz

  /// Optional notes explaining how the task was completed or any outcomes
  notes String?

  /// Order of completion for sorting purposes within user's completion history
  completion_order Int @db.Integer

  /// Flag indicating if this completion was followed by task reactivation
