import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test authenticated user attempting to access another user's profile data to
 * verify authorization boundaries. Create two separate user accounts, then
 * attempt cross-user profile access to validate proper data isolation and
 * permission enforcement. Ensures users cannot view other users' personal
 * information while maintaining strict authentication-based access controls.
 */
export async function test_api_user_profile_different_user_access(
  connection: api.IConnection,
) {
  // Create first user account
  const firstUserEmail = typia.random<string & tags.Format<"email">>();
  const firstUser = await api.functional.auth.user.join(connection, {
    body: {
      email: firstUserEmail,
      password: "SecurePassword123!",
      ip: "192.168.1.1",
      href: "https://example.com",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(firstUser);

  // Verify first user is authenticated and can access their own profile
  const ownProfile = await api.functional.todoApp.user.users.at(connection, {
    userId: firstUser.id,
  });
  typia.assert(ownProfile);

  TestValidator.equals(
    "own profile has correct user ID",
    ownProfile.id,
    firstUser.id,
  );
  TestValidator.equals(
    "own profile has correct email",
    ownProfile.email,
    firstUserEmail,
  );

  // Create second user account with different email
  // Need fresh connection context to avoid authentication conflicts
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const secondUserEmail = typia.random<string & tags.Format<"email">>();
  const secondUser = await api.functional.auth.user.join(unauthConn, {
    body: {
      email: secondUserEmail,
      password: "AnotherSecure456!",
      ip: "192.168.1.2",
      href: "https://example.com",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(secondUser);

  // Verify second user can access their own profile
  const secondUserProfile = await api.functional.todoApp.user.users.at(
    unauthConn,
    {
      userId: secondUser.id,
    },
  );
  typia.assert(secondUserProfile);

  TestValidator.equals(
    "second user profile has correct ID",
    secondUserProfile.id,
    secondUser.id,
  );
  TestValidator.equals(
    "second user profile has correct email",
    secondUserProfile.email,
    secondUserEmail,
  );

  // Test cross-user access attempts
  // Second user trying to access first user's profile should be denied
  await TestValidator.error(
    "second user cannot access first user's profile",
    async () => {
      await api.functional.todoApp.user.users.at(unauthConn, {
        userId: firstUser.id,
      });
    },
  );

  // Return to first user's authentication context
  const firstUserConn = {
    ...connection,
    headers: { Authorization: firstUser.token.access },
  };

  // First user trying to access second user's profile should be denied
  await TestValidator.error(
    "first user cannot access second user's profile",
    async () => {
      await api.functional.todoApp.user.users.at(firstUserConn, {
        userId: secondUser.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful token renewal using valid refresh token. Validates that the
 * system properly validates refresh tokens, issues new access tokens with
 * updated expiration times, and maintains session continuity.
 */
export async function test_api_auth_user_refresh_successful_renewal(
  connection: api.IConnection,
) {
  // Test 1: Refresh with explicit IP address
  const refreshRequestWithIP: ITodoAppUser.IRefresh = {
    refresh_token: RandomGenerator.alphaNumeric(32), // More realistic token format
    href: `https://todo-app.example.com/dashboard`,
    referrer: `https://todo-app.example.com/login`,
    ip: "192.168.1.100",
  } satisfies ITodoAppUser.IRefresh;

  const refreshResponse1: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.refresh(connection, {
      body: refreshRequestWithIP,
    });

  typia.assert(refreshResponse1);

  // Validate user authorization data
  TestValidator.equals("user ID format", typeof refreshResponse1.id, "string");
  TestValidator.equals(
    "user email format",
    typeof refreshResponse1.email,
    "string",
  );
  TestValidator.equals(
    "created_at exists",
    refreshResponse1.created_at !== undefined,
    true,
  );

  // Store original tokens for comparison
  const originalAccessToken = refreshResponse1.token.access;
  const originalRefreshToken = refreshResponse1.token.refresh;
  const originalExpiredAt = refreshResponse1.token.expired_at;
  const originalRefreshableUntil = refreshResponse1.token.refreshable_until;

  // Test 2: Refresh again with null IP to test nullable scenario
  const refreshRequestNoIP: ITodoAppUser.IRefresh = {
    refresh_token: originalRefreshToken,
    href: `https://todo-app.example.com/tasks`,
    referrer: `https://todo-app.example.com/dashboard`,
    ip: null,
  } satisfies ITodoAppUser.IRefresh;

  const refreshResponse2: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.refresh(connection, {
      body: refreshRequestNoIP,
    });

  typia.assert(refreshResponse2);

  // Validate token structure and properties
  const tokenData = refreshResponse2.token;
  TestValidator.equals(
    "access token exists",
    tokenData.access.length > 0,
    true,
  );
  TestValidator.equals(
    "refresh token exists",
    tokenData.refresh.length > 0,
    true,
  );
  TestValidator.equals(
    "expired_at format",
    typeof tokenData.expired_at,
    "string",
  );
  TestValidator.equals(
    "refreshable_until format",
    typeof tokenData.refreshable_until,
    "string",
  );

  // Verify new tokens are different from original (renewal actually occurred)
  TestValidator.notEquals(
    "new access token differs",
    tokenData.access,
    originalAccessToken,
  );
  TestValidator.notEquals(
    "new refresh token differs",
    tokenData.refresh,
    originalRefreshToken,
  );

  // Verify token expiration timestamps are valid and updated
  const currentTime = new Date().toISOString();
  TestValidator.predicate(
    "expired_at is future date",
    new Date(tokenData.expired_at) > new Date(currentTime),
  );
  TestValidator.predicate(
    "refreshable_until is future date",
    new Date(tokenData.refreshable_until) > new Date(currentTime),
  );

  // Validate that new expiration times are later than original (tokens should have extended validity)
  TestValidator.predicate(
    "new expired_at extends validity",
    new Date(tokenData.expired_at) >= new Date(originalExpiredAt),
  );

  // Test session continuity - verify user data remains consistent
  TestValidator.equals(
    "user ID remains consistent",
    refreshResponse1.id,
    refreshResponse2.id,
  );
  TestValidator.equals(
    "user email remains consistent",
    refreshResponse1.email,
    refreshResponse2.email,
  );
  TestValidator.equals(
    "created_at remains consistent",
    refreshResponse1.created_at,
    refreshResponse2.created_at,
  );

  // Verify authorization header is updated with new token
  TestValidator.equals(
    "authorization header set",
    connection.headers?.Authorization !== undefined,
    true,
  );
  TestValidator.equals(
    "authorization header updated with new token",
    connection.headers!.Authorization,
    tokenData.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_auth_user_refresh_invalid_token_rejection(
  connection: api.IConnection,
) {
  // Test Case 1: Malformed refresh token - completely random string
  const malformedToken = RandomGenerator.alphaNumeric(32); // Random non-JWT string

  await TestValidator.error(
    "should reject malformed refresh token - random format string",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: malformedToken,
          href: "https://example.com/refresh",
          referrer: "https://example.com/login",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Test Case 2: Token with JWT-like structure but invalid content
  const headerSegment = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"; // Valid JWT header
  const invalidPayloadSegment = "eyJzdWIiOiJ0ZXN0In0"; // Invalid/decode-failable
  const invalidSignatureSegment = "invalid_signature_not_valid_base64";

  await TestValidator.error(
    "should reject refresh token with invalid signature segment",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: `${headerSegment}.${invalidPayloadSegment}.${invalidSignatureSegment}`,
          href: "https://example.com/refresh",
          referrer: "https://example.com/login",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Test Case 3: Empty/blank refresh token
  await TestValidator.error("should reject empty refresh token", async () => {
    await api.functional.auth.user.refresh(connection, {
      body: {
        refresh_token: "",
        href: "https://example.com/refresh",
        referrer: "https://example.com/login",
      } satisfies ITodoAppUser.IRefresh,
    });
  });

  // Test Case 4: Non-JWT format token
  const nonJwtToken = RandomGenerator.alphabets(24); // Random alphabet string

  await TestValidator.error(
    "should reject non-JWT format refresh token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: nonJwtToken,
          href: "https://example.com/refresh",
          referrer: "https://example.com/login",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // Test Case 5: Token with valid JWT front but invalid remainder
  const validHeaderSegment = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"; // Valid JWT-looking
  const invalidRemainderSegment = "invalid_not_base64_url_safe_!@#$%";

  await TestValidator.error(
    "should reject refresh token with valid-looking start but corrupted content",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: `${validHeaderSegment}.${invalidRemainderSegment}.${invalidRemainderSegment}`,
          href: "https://example.com/refresh",
          referrer: "https://example.com/login",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );
}

