  );

  // Step 7: Test inactive settings filtering within production environment
  const inactiveProdRequest = {
    page: 1,
    limit: 20,
    environment_scope: "production",
    is_active: false,
  } satisfies ITodoAppSystemSettings.IRequest;

  const inactiveProdFiltered =
