import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_category_creation_constraints(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account and establish authentication
  const email = typia.random<string & tags.Format<"email">>();
  const href = "http://localhost:3000";
  const referrer = "http://localhost:3000";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: RandomGenerator.alphaNumeric(8),
      href,
      referrer,
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create initial category with valid name
  const firstCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: "Work Tasks",
        description: "Professional assignments and deadlines",
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(firstCategory);

  // Step 3: Attempt to create category with duplicate name - should fail
  await TestValidator.error(
    "duplicate category name should be rejected",
    async () => {
      await api.functional.todoApp.user.categories.create(connection, {
        body: {
          name: "Work Tasks", // Same name as first category
          description: "Duplicate work category",
        } satisfies ITodoAppCategory.ICreate,
      });
    },
  );

  // Step 4: Create category with modified name - should succeed
  const secondCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: "Work Projects", // Similar but distinct name
        description: "Alternative work task organization",
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(secondCategory);

  // Step 5: Verify both categories exist and are distinct
  TestValidator.notEquals(
    "created categories should have different IDs",
    firstCategory.id,
    secondCategory.id,
  );

  TestValidator.equals(
    "first category name should be retained",
    firstCategory.name,
    "Work Tasks",
  );

  TestValidator.equals(
    "second category should have different name",
    secondCategory.name,
    "Work Projects",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful search and retrieval of tasks within a specific category.
 * This comprehensive test validates that authenticated users can filter, sort,
 * and paginate tasks belonging to their personal categories. The test covers
 * basic search functionality with default parameters, verifies proper
 * pagination behavior, and ensures only tasks within the specified category are
 * returned.
 *
 * Complete workflow:
 *
 * 1. Create user account for authentication
 * 2. Create test category to organize tasks
 * 3. Create multiple diverse todo tasks in the category (pending, in-progress,
 *    completed)
 * 4. Create tasks in different category to test isolation
 * 5. Test basic category task search with default parameters
 * 6. Test filtering by status (pending, completed)
 * 7. Test filtering by priority (Low, Medium, High)
 * 8. Test text search within category tasks
 * 9. Test pagination functionality
 * 10. Verify task isolation - ensure only category-specific tasks are returned
 * 11. Test sorting by different fields (created_at, priority, completion_order)
 */
export async function test_api_category_task_search_success(
  connection: api.IConnection,
) {
  // Step 1: Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userEmail,
        password: "SecurePass123",
        href: "https://todo-app.example.com/join",
        referrer: "https://todo-app.example.com",
      } satisfies ITodoAppUser.IJoin,
    },
  );
  typia.assert(user);

  // Step 2: Create test category to organize tasks
  const category: ITodoAppCategory =
    await api.functional.todoApp.user.categories.create(connection, {
      body: {
        name: "Work Projects",
        description: "Tasks related to professional projects",
      } satisfies ITodoAppCategory.ICreate,
    });
  typia.assert(category);

  // Create another category to test task isolation
  const personalCategory: ITodoAppCategory =
    await api.functional.todoApp.user.categories.create(connection, {
      body: {
        name: "Personal Tasks",
        description: "Personal life tasks",
      } satisfies ITodoAppCategory.ICreate,
    });
  typia.assert(personalCategory);

  // Step 3: Create multiple diverse todo tasks in the target category
  const workTasks: ITodoAppTask[] = [];

  // Create pending tasks
  const pendingTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Pending Work Task 1",
        description: "This is a pending high priority work task",
        todo_app_category_id: category.id,
        priority: "High",
        due_date: new Date(Date.now() + 86400000).toISOString(), // tomorrow
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(pendingTask1);

  const pendingTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Pending Work Task 2",
        description: "This is a pending medium priority work task",
        todo_app_category_id: category.id,
        priority: "Medium",
        due_date: new Date(Date.now() + 86400000 * 3).toISOString(), // 3 days
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(pendingTask2);

  // Create in-progress tasks
  const inProgressTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "In Progress Work Task 3",
        description: "Currently working on this medium priority task",
        todo_app_category_id: category.id,
        priority: "Medium",
        due_date: new Date(Date.now() + 86400000 * 2).toISOString(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(inProgressTask1);

  const inProgressTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "In Progress Work Task 4",
        description: "This is an in-progress high priority task",
        todo_app_category_id: category.id,
        priority: "High",
        due_date: new Date(Date.now() + 86400000 * 4).toISOString(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(inProgressTask2);

  // Create completed tasks
  const completedTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Completed Work Task 5",
        description: "This completed work task is ready for testing",
        todo_app_category_id: category.id,
        priority: "Low",
        completion_order: 10,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(completedTask1);

  const completedTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Completed Work Task 6",
        description: "Another completed low priority work task",
        todo_app_category_id: category.id,
        priority: "Low",
        completion_order: 20,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  workTasks.push(completedTask2);

  // Validate that all tasks were created successfully
  for (const task of workTasks) {
    typia.assert(task);
  }

  // Step 4: Create tasks in personal category to test isolation
  const otherTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Personal shopping task",
        description: "Buy groceries",
        todo_app_category_id: personalCategory.id,
        priority: "Medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );

  const otherTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Exercise routine",
        description: "Morning workout",
        todo_app_category_id: personalCategory.id,
        priority: "High",
      } satisfies ITodoAppTask.ICreate,
    },
  );

  typia.assert(otherTask1);
  typia.assert(otherTask2);

  // Step 5: Test basic category task search with default parameters
  const basicSearch = await api.functional.todoApp.user.categories.tasks.index(
    connection,
    {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(basicSearch);

  // Verify pagination info
  TestValidator.predicate(
    "basic search has work category tasks",
    basicSearch.data.length > 0,
  );
  TestValidator.equals(
    "basic search current page",
    basicSearch.pagination.current,
    1,
  );
  TestValidator.equals(
    "basic search per-page limit",
    basicSearch.pagination.limit,
    10,
  );

  // Step 6: Test filtering by status
  const pendingTasks = await api.functional.todoApp.user.categories.tasks.index(
    connection,
    {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pendingTasks);

  TestValidator.predicate(
    "all pending tasks have pending status",
    pendingTasks.data.every((task) => task.status === "pending"),
  );

  const completedTasks =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        status: "completed",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(completedTasks);

  TestValidator.predicate(
    "all completed tasks have completed status",
    completedTasks.data.every((task) => task.status === "completed"),
  );

  // Step 7: Test filtering by priority
  const highPriorityTasks =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        priority: "High",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(highPriorityTasks);

  TestValidator.predicate(
    "all high priority tasks have high priority",
    highPriorityTasks.data.every((task) => task.priority === "High"),
  );

  const lowPriorityTasks =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        priority: "Low",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(lowPriorityTasks);

  TestValidator.predicate(
    "all low priority tasks have low priority",
    lowPriorityTasks.data.every((task) => task.priority === "Low"),
  );

  // Step 8: Test text search within category tasks
  const searchWorkTasks =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        search: "Work Task",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchWorkTasks);

  TestValidator.predicate(
    "search results contain work task text",
    searchWorkTasks.data.length > 0,
  );

  // Step 9: Test pagination functionality
  const page1 = await api.functional.todoApp.user.categories.tasks.index(
    connection,
    {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page1);

  const page2 = await api.functional.todoApp.user.categories.tasks.index(
    connection,
    {
      categoryId: category.id,
      body: {
        page: 2,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page2);

  TestValidator.predicate(
    "pagination returns different results",
    page1.data.length <= 5 && page2.data.length <= 5,
  );
  TestValidator.equals("page 1 shows page 1", page1.pagination.current, 1);
  TestValidator.equals("page 2 shows page 2", page2.pagination.current, 2);

  // Step 10: Verify task isolation - ensure only category-specific tasks are returned
  // All tasks in the search results should belong to the work category
  for (const taskSummary of basicSearch.data) {
    // The summary should contain tasks that match our work task patterns
    TestValidator.predicate(
      "task title contains work-related text",
      taskSummary.title.includes("Work Task"),
    );
  }

  // Step 11: Test sorting by different fields
  const sortedByPriority =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        sort_by: "priority",
        sort_order: "desc",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(sortedByPriority);

  TestValidator.predicate(
    "tasks are sorted by priority descending",
    sortedByPriority.data.length > 0,
  );

  const sortedByCreated =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 25,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(sortedByCreated);

  TestValidator.predicate(
    "tasks are sorted by creation date ascending",
    sortedByCreated.data.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test text-based search functionality within category task context.
 *
 * This test validates comprehensive text search capabilities within a specific
 * category, testing various search patterns including partial text matching,
 * case-insensitive search, multi-term queries, and special character handling.
 * The test creates a category with multiple tasks containing different text
 * patterns, then performs various search operations to verify the search
 * functionality works correctly.
 *
 * Test workflow:
 *
 * 1. Create authenticated user account
 * 2. Create a category for organizing tasks
 * 3. Create multiple tasks with varied titles and descriptions
 * 4. Test basic text search with partial matching
 * 5. Test case-insensitive search behavior
 * 6. Test multi-term search queries
 * 7. Test special character handling
 * 8. Test empty result scenarios
 * 9. Validate search result pagination
 *
 * Each test case verifies that search results contain the expected tasks based
 * on title and description content matching.
 */
export async function test_api_category_task_search_text_filter(
  connection: api.IConnection,
) {
  // 1. Create authenticated user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      ip: "127.0.0.1",
      href: "https://example.com",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);
  TestValidator.predicate("user created successfully", user.id !== undefined);
  TestValidator.equals("user email matches", user.email, userEmail);

  // 2. Create a category for organizing tasks
  const categoryName = RandomGenerator.name();
  const category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: categoryName,
        description: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(category);
  TestValidator.equals("category name matches", category.name, categoryName);
  TestValidator.predicate(
    "category belongs to user",
    category.user.id === user.id,
  );

  // 3. Create multiple tasks with varied titles and descriptions
  const tasks = await ArrayUtil.asyncRepeat(6, async (index) => {
    const titles = [
      "Complete project documentation",
      "update user interface design",
      "Review code changes",
      "Fix database connection issues",
      "Deploy new features",
      "Test authentication system",
    ] as const;

    const descriptions = [
      "Finish the technical documentation for the main project",
      "Redesign the UI with modern design principles and accessibility",
      "Review latest pull requests and provide feedback",
      "Resolve connection timeouts and improve performance",
      "Deploy all completed features to production environment",
      "Test login/logout functionality with various scenarios",
    ] as const;

    return await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: titles[index],
        description: descriptions[index],
        todo_app_category_id: category.id,
        priority: RandomGenerator.pick(["Low", "Medium", "High"]),
        due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        completion_order: index,
      } satisfies ITodoAppTask.ICreate,
    });
  });

  tasks.forEach((task) => typia.assert(task));
  TestValidator.equals("all tasks created", tasks.length, 6);

  // 4. Test basic text search with partial matching
  const searchForDocumentation =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "documentation",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchForDocumentation);

  TestValidator.predicate(
    "documentation search returns results",
    searchForDocumentation.data.length > 0,
  );
  TestValidator.predicate(
    "results contain documentation text",
    searchForDocumentation.data.some((task) =>
      task.title.toLowerCase().includes("documentation"),
    ),
  );

  // 5. Test case-insensitive search behavior
  const searchForDESIGN =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "DESIGN",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchForDESIGN);

  TestValidator.predicate(
    "uppercase design search returns results",
    searchForDESIGN.data.length > 0,
  );
  TestValidator.predicate(
    "results contain design text (case insensitive)",
    searchForDESIGN.data.some((task) =>
      task.title.toLowerCase().includes("design"),
    ),
  );

  // 6. Test multi-term search queries
  const searchForDatabaseConnection =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "database connection",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchForDatabaseConnection);

  TestValidator.predicate(
    "multi-term database connection search returns results",
    searchForDatabaseConnection.data.length > 0,
  );
  TestValidator.predicate(
    "results contain database connection terms",
    searchForDatabaseConnection.data.some(
      (task) =>
        task.title.toLowerCase().includes("database") &&
        task.title.toLowerCase().includes("connection"),
    ),
  );

  // 7. Test special character handling
  const searchForReview =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "review code",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchForReview);

  TestValidator.predicate(
    "review code search returns results",
    searchForReview.data.length > 0,
  );
  TestValidator.predicate(
    "results contain review or code terms",
    searchForReview.data.some(
      (task) =>
        task.title.toLowerCase().includes("review") ||
        task.title.toLowerCase().includes("code"),
    ),
  );

  // 8. Test empty result scenarios
  const searchForNonExistent =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "xyz123nonexistent456abc",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchForNonExistent);

  TestValidator.equals(
    "non-existent search returns empty results",
    searchForNonExistent.data.length,
    0,
  );
  TestValidator.equals(
    "pagination shows zero records",
    searchForNonExistent.pagination.records,
    0,
  );

  // 9. Test pagination with search results
  const searchWithPagination =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 2,
        search: "task",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchWithPagination);

  TestValidator.predicate(
    "pagination search returns results",
    searchWithPagination.data.length > 0,
  );
  TestValidator.predicate(
    "pagination respects limit",
    searchWithPagination.data.length <= 2,
  );
  TestValidator.equals(
    "pagination info is valid",
    searchWithPagination.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit matches",
    searchWithPagination.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "pagination records positive",
    searchWithPagination.pagination.records > 0,
  );

  // 10. Test search with status filter combination
  const searchWithStatusFilter =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "project",
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(searchWithStatusFilter);

  TestValidator.predicate(
    "search with status filter returns results",
    searchWithStatusFilter.data.length >= 0,
  );
  searchWithStatusFilter.data.forEach((task) => {
    TestValidator.equals(
      "all results are pending status",
      task.status,
      "pending",
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test priority-based filtering of tasks within category context.
 *
 * This comprehensive test validates the priority-based task filtering
 * functionality within the todo application's category system. It ensures users
 * can effectively filter tasks by Low, Medium, and High priority levels both
 * individually and in combination, supporting efficient task organization and
 * workflow management.
 *
 * The test covers:
 *
 * 1. User authentication and category creation setup
 * 2. Task creation with diverse priority assignments across all three levels
 * 3. Individual priority filtering for each priority level (Low, Medium, High)
 * 4. Combined priority filtering to test multiple priority selection
 * 5. Priority-based sorting functionality validation
 * 6. Priority distribution visibility across paginated results
 * 7. Edge cases including empty results and pagination boundaries
 *
 * This ensures the priority filtering system works correctly for personal task
 * management workflows, enabling users to focus on specific priority levels and
 * maintain organized task hierarchies within their categories.
 */
export async function test_api_category_task_search_priority_filter(
  connection: api.IConnection,
) {
  // Step 1: Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePass123!",
      ip: "127.0.0.1",
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create a category for organizing tasks
  const category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: "Work Projects",
        description: "Priority-based task organization for work projects",
