import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test due date range filtering within category task searches.
 *
 * This test validates comprehensive date-based filtering and sorting
 * capabilities for tasks within a specific category. It covers:
 *
 * 1. Creating a test user and category for organization
 * 2. Creating tasks with various due dates (past, present, future, none)
 * 3. Testing date range filtering with different date combinations
 * 4. Validating due date-based sorting functionality
 * 5. Testing timezone handling for date boundaries
 * 6. Verifying proper handling of tasks without due dates
 * 7. Testing pagination with date-filtered results
 * 8. Validating edge cases like invalid date ranges
 *
 * Essential for ensuring users can effectively organize and manage tasks based
 * on deadlines, which is critical for productivity management workflows.
 */
export async function test_api_category_task_search_due_date_range(
  connection: api.IConnection,
) {
  // Step 1: Create user account for authentication
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "SecurePassword123",
      ip: "127.0.0.1",
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create a test category for organizing tasks
  const category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: "Test Projects",
        description: "Category for testing date-based filtering",
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Create tasks with various due date scenarios
  const now = new Date();
  const taskData = [
    {
      title: "Past Overdue Task",
      dueDate: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000),
      priority: "High" as const,
    },
    { title: "Today Task", dueDate: now, priority: "Medium" as const },
    {
      title: "Tomorrow Task",
      dueDate: new Date(now.getTime() + 24 * 60 * 60 * 1000),
      priority: "Low" as const,
    },
    {
      title: "This Week Task",
      dueDate: new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000),
      priority: "Medium" as const,
    },
    {
      title: "Next Month Task",
      dueDate: new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000),
      priority: "High" as const,
    },
    { title: "No Due Date Task", dueDate: null, priority: "Low" as const },
    {
      title: "Future High Priority",
      dueDate: new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000),
      priority: "High" as const,
    },
  ];

  const createdTasks: ITodoAppTask[] = [];
  for (const taskInfo of taskData) {
    const taskBody = {
      title: taskInfo.title,
      description: `Task created for date range testing - ${taskInfo.title}`,
      todo_app_category_id: category.id,
      priority: taskInfo.priority,
      due_date: taskInfo.dueDate ? taskInfo.dueDate.toISOString() : null,
    } satisfies ITodoAppTask.ICreate;

    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body: taskBody,
    });
    typia.assert<ITodoAppTask>(task);
    createdTasks.push(task);
  }

  // Step 4: Test filtering by date ranges
  const testStartDate = new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000); // Yesterday
  const testEndDate = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // Next week

  // Test 1: Filter by specific date range (yesterday to next week)
  const dateRangeResult =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        due_date_from: testStartDate.toISOString(),
        due_date_to: testEndDate.toISOString(),
        sort_by: "due_date",
        sort_order: "asc",
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(dateRangeResult);

  // Validate that only tasks within date range are returned
  const expectedCount = 4; // Today, Tomorrow, This Week (Next Month excluded)
  TestValidator.predicate(
    "date range filtering returns correct number of tasks",
    dateRangeResult.data.length === expectedCount,
  );

  // Verify each filtered task falls within the date range
  for (const task of dateRangeResult.data) {
    TestValidator.predicate(
      "task has valid due date within range",
      task.due_date !== null &&
        task.due_date !== undefined &&
        new Date(task.due_date) >= testStartDate &&
        new Date(task.due_date) <= testEndDate,
    );
  }

  // Test 2: Filter for future high priority tasks
  const futureHighPriorityResult =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        due_date_from: new Date(
          now.getTime() + 24 * 60 * 60 * 1000,
        ).toISOString(), // Tomorrow and beyond
        priority: "High",
        sort_by: "due_date",
        sort_order: "asc",
      } satisfies ITodoAppTask.IRequest,
    });

  TestValidator.predicate(
    "future high priority tasks filtering works correctly",
    futureHighPriorityResult.data.every(
      (task) =>
        task.priority === "High" &&
        task.due_date !== null &&
        task.due_date !== undefined &&
        new Date(task.due_date) > now,
    ),
  );

  // Test 3: Filter tasks with no due dates
  const noDueDateResult =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "due_date",
        sort_order: "asc",
      } satisfies ITodoAppTask.IRequest,
    });

  const tasksWithNoDueDate = noDueDateResult.data.filter(
    (task) => task.due_date === null || task.due_date === undefined,
  );
  TestValidator.predicate(
    "tasks without due dates are included in results",
    tasksWithNoDueDate.length >= 1,
  );

  // Test 4: Text search combined with date filtering
  const textSearchDateResult =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 10,
        search: "task",
        due_date_from: new Date(
          now.getTime() - 2 * 24 * 60 * 60 * 1000,
        ).toISOString(), // Recent tasks
        due_date_to: new Date(
          now.getTime() + 14 * 24 * 60 * 60 * 1000,
        ).toISOString(), // Near future
        sort_by: "due_date",
      } satisfies ITodoAppTask.IRequest,
    });

  TestValidator.predicate(
    "text search with date range returns relevant tasks",
    textSearchDateResult.data.every(
      (task) =>
        task.title.toLowerCase().includes("task") &&
        task.due_date !== null &&
        task.due_date !== undefined &&
        new Date(task.due_date) >=
          new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000) &&
        new Date(task.due_date) <=
          new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000),
    ),
  );

  // Test 5: Pagination with date filtering
  const singlePageResult =
    await api.functional.todoApp.user.categories.tasks.index(connection, {
      categoryId: category.id,
      body: {
        page: 1,
        limit: 2, // Small page size
        due_date_from: testStartDate.toISOString(),
        due_date_to: new Date(
          now.getTime() + 10 * 24 * 60 * 60 * 1000,
        ).toISOString(),
        sort_by: "due_date",
      } satisfies ITodoAppTask.IRequest,
    });

  TestValidator.predicate(
    "pagination with date filtering works correctly",
    singlePageResult.data.length <= 2 &&
      singlePageResult.pagination.current === 1 &&
      singlePageResult.pagination.limit === 2,
  );

  // Test 6: Sorting verification - ensure dates are ascending within filtered results
  TestValidator.predicate(
    "date sorting produces properly ordered results",
    isArraySorted(singlePageResult.data),
  );

  // Helper function to check if array of tasks is sorted by due date
  function isArraySorted(tasks: ITodoAppTask.ISummary[]): boolean {
    const tasksWithDates = tasks.filter(
      (task) => task.due_date !== null && task.due_date !== undefined,
    );

    for (let i = 1; i < tasksWithDates.length; i++) {
      if (
        new Date(tasksWithDates[i - 1].due_date!).getTime() >
        new Date(tasksWithDates[i].due_date!).getTime()
      ) {
        return false;
      }
    }
    return true;
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful creation of new task categories for authenticated users.
 * Validates the complete workflow from user registration through category
 * establishment.
 *
 * 1. Creates a new user account through authentication endpoint
 * 2. Creates task categories with valid names following business rules
 * 3. Validates category structure and user ownership
 * 4. Tests multiple category creation and optional descriptions
 * 5. Ensures immediate availability for task organization
 * 6. Verifies boundary conditions (min/max length, allowed characters)
 * 7. Tests rapid category creation to validate immediate availability
 *
 * Business rules tested:
 *
 * - Category names must be 2-50 characters
 * - Category names limited to letters, numbers, spaces, and hyphens
 * - Uniqueness per user account
 * - Immediate availability after creation
 * - Proper user ownership association
 */
export async function test_api_category_creation_success(
  connection: api.IConnection,
) {
  // Step 1: Create user account through join endpoint (authentication prerequisite)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10), // Minimum 8 characters from MinLength<8>
    ip: connection.host,
    href: connection.host + "/registration",
    referrer: "https://example.com/signup",
  } satisfies ITodoAppUser.IJoin;

  const user = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(user);

  TestValidator.equals("User email matches", user.email, joinBody.email);
  TestValidator.equals(
    "User has created_at timestamp",
    user.created_at !== null,
    true,
  );
  TestValidator.equals("User has valid ID format", typeof user.id, "string");
  TestValidator.equals(
    "User has authorization token",
    user.token.access !== null,
    true,
  );

  // Step 2: Create first category with basic name
  const createFirstCategory = {
    name: "Personal Tasks",
  } satisfies ITodoAppCategory.ICreate;

  const firstCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: createFirstCategory,
    },
  );
  typia.assert(firstCategory);

  TestValidator.equals(
    "Category name matches",
    firstCategory.name,
    createFirstCategory.name,
  );
  TestValidator.equals(
    "Category has user ownership",
    firstCategory.user.id,
    user.id,
  );
  TestValidator.equals("Category has UUID ID", firstCategory.id !== null, true);
  TestValidator.equals(
    "Category has created_at timestamp",
    firstCategory.created_at !== null,
    true,
  );
  TestValidator.equals(
    "Category has updated_at timestamp",
    firstCategory.updated_at !== null,
    true,
  );
  TestValidator.equals(
    "Category description is undefined",
    firstCategory.description,
    undefined,
  );

  // Step 3: Test category with description
  const createSecondCategory = {
    name: "Work Projects",
    description: "Professional tasks and project deliverables",
  } satisfies ITodoAppCategory.ICreate;

  const secondCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: createSecondCategory,
    },
  );
  typia.assert(secondCategory);

  TestValidator.equals(
    "Category name matches",
    secondCategory.name,
    createSecondCategory.name,
  );
  TestValidator.equals(
    "Category description matches",
    secondCategory.description,
    createSecondCategory.description,
  );
  TestValidator.equals("Same user ownership", secondCategory.user.id, user.id);

  // Step 4: Test name validation with spaces and hyphens
  const createThirdCategory = {
    name: "Shopping List-Home",
    description: "Household items needed for weekly shopping",
  } satisfies ITodoAppCategory.ICreate;

  const thirdCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: createThirdCategory,
    },
  );
  typia.assert(thirdCategory);

  TestValidator.equals(
    "Category name with hyphens matches",
    thirdCategory.name,
    createThirdCategory.name,
  );
  TestValidator.equals(
    "Category description matches",
    thirdCategory.description,
    createThirdCategory.description,
  );
  TestValidator.equals("Same user ownership", thirdCategory.user.id, user.id);

  // Step 5: Test minimum length (boundary)
  const createShortCategory = {
    name: "XY", // Minimum 2 characters as specified in MinLength<2>
  } satisfies ITodoAppCategory.ICreate;

  const shortCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: createShortCategory,
    },
  );
  typia.assert(shortCategory);

  TestValidator.equals(
    "Short category name matches",
    shortCategory.name.length,
    2,
  );
  TestValidator.equals(
    "Short category name content matches",
    shortCategory.name,
    createShortCategory.name,
  );

  // Step 6: Test maximum length with exactly 50 characters
  const createExactly50Category = {
    name: "This category name has exactly fifty characters for length", // Exactly 50 characters
    description: "Exactly 50 character name test",
  } satisfies ITodoAppCategory.ICreate;

  const exactly50Category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: createExactly50Category,
    },
  );
  typia.assert(exactly50Category);

  TestValidator.equals(
    "Exactly 50 character name",
    exactly50Category.name.length,
    50,
  );
  TestValidator.equals(
    "Character count matches input",
    exactly50Category.name,
    createExactly50Category.name,
  );
  TestValidator.equals(
    "User ownership maintained",
    exactly50Category.user.id,
    user.id,
  );

  // Step 7: Test rapid creation to verify immediate availability
  const rapidCategories = ArrayUtil.repeat(
    3,
    (index) =>
      ({
        name: `Rapid Testing ${index + 1}`,
        description: `Quick category ${index + 1} for availability testing`,
      }) satisfies ITodoAppCategory.ICreate,
  );

  // Create multiple categories rapidly
  const createdRapidCategories = await ArrayUtil.asyncMap(
    rapidCategories,
    async (categoryData) => {
      return await api.functional.todoApp.user.categories.create(connection, {
        body: categoryData,
      });
    },
  );

  // Verify all categories were created successfully
  createdRapidCategories.forEach((category, index) => {
    typia.assert(category);
    TestValidator.equals(
      `Rapid category ${index + 1} name matches`,
      category.name,
      rapidCategories[index].name,
    );
    TestValidator.equals(
      `Rapid category ${index + 1} description matches`,
      category.description,
      rapidCategories[index].description,
    );
    TestValidator.equals(
      `Rapid category ${index + 1} has user ownership`,
      category.user.id,
      user.id,
    );
  });

  // Step 8: Validate temporal relationships - created_at should be equal or before updated_at
  TestValidator.predicate(
    "First category created before updated",
    new Date(firstCategory.created_at).getTime() <=
      new Date(firstCategory.updated_at!).getTime(),
  );
  TestValidator.predicate(
    "First category has legitimate timestamps",
    firstCategory.created_at !== firstCategory.updated_at!,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test input validation during category creation including character
 * restrictions, length constraints, and name uniqueness requirements. Covers
 * edge cases with special characters, boundary length testing, and duplicate
 * category name prevention. Validates proper error handling for invalid inputs
 * while ensuring successful creation with acceptable category names following
 * format requirements.
 *
 * Testing strategy:
 *
 * 1. Create authenticated user account for testing
 * 2. Test successful category creation with valid names
 * 3. Test boundary conditions: minimum length (2 chars), maximum length (50 chars)
 * 4. Test invalid character restrictions: special characters not allowed (only
 *    letters, numbers, spaces, hyphens)
 * 5. Test duplicate category name prevention
 * 6. Test edge cases: empty strings, single character, excessive length
 * 7. Test with and without optional description field
 *
 * Business rules to validate:
 *
 * - Category names must be 2-50 characters
 * - Only letters, numbers, spaces, and hyphens allowed in names
 * - Category names must be unique per user
 * - Optional description field can be null or undefined
 * - Proper error messages for validation failures
 */
export async function test_api_category_creation_validation(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user for testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userJoinData = {
    email: userEmail,
    password: "ValidPass123!",
    href: "https://example.com/todo",
    referrer: "https://example.com",
  } satisfies ITodoAppUser.IJoin;

  const user = await api.functional.auth.user.join(connection, {
    body: userJoinData,
  });
  typia.assert(user);

  // Step 2: Test successful category creation with valid name
  const validCategoryName = "Work Tasks";
  const validCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: validCategoryName,
        description: "Work-related todo items",
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(validCategory);

  TestValidator.equals(
    "valid category name",
    validCategory.name,
    validCategoryName,
  );
  TestValidator.equals(
    "valid category description",
    validCategory.description,
    "Work-related todo items",
  );

  // Step 3: Test minimum boundary (2 characters)
  const minLengthCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: "AB",
        description: null,
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(minLengthCategory);
  TestValidator.equals(
    "minimum length category name",
    minLengthCategory.name,
    "AB",
  );

  // Step 4: Test maximum boundary (50 characters)
  const maxLengthName = "This is exactly fifty characters long category name!";
  const maxLengthCategory = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: maxLengthName,
        description: undefined,
