import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test updating a task's due date to validate deadline management
 * functionality.
 *
 * This test creates a user account, creates a new task, and then updates the
 * task with a future due date to ensure the system properly handles temporal
 * planning constraints. Validates that due date updates follow system
 * constraints (future dates only, within 1 year) and properly update the task's
 * temporal planning context.
 *
 * Test flow:
 *
 * 1. Create new user account for authentication
 * 2. Create a new todo task with basic information
 * 3. Update the task with a future due date
 * 4. Verify the due date was properly updated
 * 5. Test edge case: updating with a past date should fail
 * 6. Test edge case: updating with a date beyond 1 year should fail
 */
export async function test_api_task_update_due_date(
  connection: api.IConnection,
) {
  // Create user account for authentication
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      href: "https://example.com",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Create a new task
  const task = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: "Complete quarterly report",
      description: "Prepare and review Q4 financial report",
      priority: "High",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task);

  // Generate a valid future due date (within 1 year from now)
  const oneMonthFromNow = new Date(
    Date.now() + 30 * 24 * 60 * 60 * 1000,
  ).toISOString();

  // Update task with future due date
  const updatedTask = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: task.id,
      body: {
        due_date: oneMonthFromNow,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(updatedTask);

  // Verify due date was updated correctly
  TestValidator.equals(
    "due date updated",
    updatedTask.due_date,
    oneMonthFromNow,
  );
  TestValidator.predicate(
    "due date is future date",
    new Date(updatedTask.due_date!) > new Date(),
  );

  // Test updating with past date should fail
  const pastDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // Yesterday
  await TestValidator.error("should fail with past date", async () => {
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: task.id,
      body: {
        due_date: pastDate,
      } satisfies ITodoAppTask.IUpdate,
    });
  });

  // Test updating with date beyond 1 year should fail
  const beyondOneYearDate = new Date(
    Date.now() + 366 * 24 * 60 * 60 * 1000,
  ).toISOString(); // More than 1 year
  await TestValidator.error("should fail with date beyond 1 year", async () => {
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: task.id,
      body: {
        due_date: beyondOneYearDate,
      } satisfies ITodoAppTask.IUpdate,
    });
  });

  // Test updating due date to null (removing deadline)
  const taskWithNoDueDate = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: task.id,
      body: {
        due_date: null,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(taskWithNoDueDate);
  TestValidator.equals("due date removed", taskWithNoDueDate.due_date, null);

  // Test only updating due date without affecting other fields
  const titleBeforeUpdate = updatedTask.title;
  const priorityBeforeUpdate = updatedTask.priority;

  const anotherFutureDate = new Date(
    Date.now() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 7 days from now
  const taskWithNewDueDate = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: task.id,
      body: {
        due_date: anotherFutureDate,
      } satisfies ITodoAppTask.IUpdate,
    },
  );

  typia.assert(taskWithNewDueDate);
  TestValidator.equals(
    "title unchanged",
    taskWithNewDueDate.title,
    titleBeforeUpdate,
  );
  TestValidator.equals(
    "priority unchanged",
    taskWithNewDueDate.priority,
    priorityBeforeUpdate,
  );
  TestValidator.equals(
    "due date updated to new value",
    taskWithNewDueDate.due_date,
    anotherFutureDate,
  );

  // Test due date validation during initial task creation with valid date
  const taskWithDueDate = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Weekly team meeting",
        description: "Schedule and prepare agenda",
        priority: "Medium",
        due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskWithDueDate);
  TestValidator.predicate(
    "task created with valid due date",
    taskWithDueDate.due_date !== null,
  );

  // Test due date validation during initial task creation with past date should fail
  await TestValidator.error(
    "task creation should fail with past due date",
    async () => {
      await api.functional.todoApp.user.tasks.create(connection, {
        body: {
          title: "Update contact information",
          description: "Update client contact details",
          priority: "Low",
          due_date: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(), // Yesterday
        } satisfies ITodoAppTask.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test updating a task to assign it to a specific category.
 *
 * This test validates the complete category assignment workflow by:
 *
 * 1. Creating a new user account for authentication
 * 2. Creating a category for task organization
 * 3. Creating a task without initial category assignment
 * 4. Updating the task to assign it to the created category
 * 5. Validating the task now includes complete category information
 *
 * The test ensures foreign key validation works correctly and that tasks can be
 * properly organized within user-owned categories.
 */
export async function test_api_task_update_category_assignment(
  connection: api.IConnection,
) {
  // Step 1: Create user account and authenticate
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePassword123",
      ip: "192.168.1.1",
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create a category for task organization
  const category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Create a task without category assignment
  const task = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 1 }),
      description: RandomGenerator.paragraph({ sentences: 3 }),
      priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
      due_date: new Date(Date.now() + 86400000 * 7).toISOString(), // 7 days from now, within 1 year constraint
      completion_order: 1,
      // No todo_app_category_id - task created without category
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task);

  // Validate task was created without category
  TestValidator.equals("task initially has no category", task.category, null);

  // Step 4: Update task to assign it to the category
  const updatedTask = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: task.id,
      body: {
        todo_app_category_id: category.id,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(updatedTask);

  // Step 5: Validate category assignment was successful
  TestValidator.equals(
    "task now has category",
    updatedTask.category !== null,
    true,
  );
  TestValidator.equals(
    "category ID matches",
    updatedTask.category!.id,
    category.id,
  );
  TestValidator.equals(
    "category name matches",
    updatedTask.category!.name,
    category.name,
  );
  TestValidator.equals("task title unchanged", updatedTask.title, task.title);
  TestValidator.equals(
    "task description unchanged",
    updatedTask.description,
    task.description,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful deletion of a task. Create a task and then delete it to
 * verify the complete task removal workflow. Validates that the task is
 * permanently removed from the system and that ownership validation prevents
 * unauthorized deletion (though this test assumes authorized deletion by the
 * task owner).
 */
export async function test_api_task_delete_success(
  connection: api.IConnection,
) {
  // Register a new user to establish authentication context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: "127.0.0.1",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);
  TestValidator.predicate(
    "user registration successful",
    user.email === userEmail,
  );

  // Create a task to delete
  const createTaskData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 4,
      wordMax: 10,
    }),
    priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 1 week from now
    completion_order: 1,
  } satisfies ITodoAppTask.ICreate;

  const createdTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: createTaskData,
    },
  );
  typia.assert(createdTask);
  TestValidator.predicate(
    "task created successfully",
    createdTask.title === createTaskData.title,
  );

  // Delete the task
  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: createdTask.id,
  });

  // Verify the deletion by checking if the task is removed from the system
  // Since we cannot directly query a deleted task, we can attempt to delete it again to ensure it's gone
  await TestValidator.error("deleted task cannot be found", async () => {
    await api.functional.todoApp.user.tasks.erase(connection, {
      taskId: createdTask.id,
    });
  });

  // Verify that attempting to create another task with the same data works (no conflicts)
  const recreatedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: createTaskData,
    },
  );
  typia.assert(recreatedTask);
  TestValidator.predicate(
    "task can be recreated with same data",
    recreatedTask.title === createTaskData.title,
  );
  TestValidator.predicate(
    "recreated task has different ID",
    recreatedTask.id !== createdTask.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test that tasks cannot be deleted by non-owners.
 *
 * This test validates the security boundary enforcement of the todo application
 * by ensuring that tasks can only be deleted by their rightful owners. The test
 * creates two separate user accounts, has one create a task, then verifies that
 * the second user is prevented from deleting that task through proper ownership
 * enforcement policies.
 *
 * @param connection - The API connection object
 * @returns A promise that resolves when the test completes
 */
export async function test_api_task_prevents_cross_user_deletion(
  connection: api.IConnection,
): Promise<void> {
  // Create first user who will own the task
  const firstUserEmail = typia.random<string & tags.Format<"email">>();
  const firstUser = await api.functional.auth.user.join(connection, {
    body: {
      email: firstUserEmail,
      password: "password123",
      ip: "127.0.0.1",
      href: "https://example.com/auth",
      referrer: "https://example.com/join",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(firstUser);

  // Create a task as the first user
  const taskData = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
  } satisfies ITodoAppTask.ICreate;

  const firstUserTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: taskData,
    },
  );
  typia.assert(firstUserTask);

  TestValidator.equals(
    "task owner should be first user",
    firstUserTask.user.id,
    firstUser.id,
  );

  // Create second user who should NOT be able to delete first user's task
  const secondUserEmail = typia.random<string & tags.Format<"email">>();
  const secondUser = await api.functional.auth.user.join(connection, {
    body: {
      email: secondUserEmail,
      password: "password456",
      ip: "127.0.0.1",
      href: "https://example.com/auth",
      referrer: "https://example.com/join",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(secondUser);

  // Verify second user is different from first user
  TestValidator.notEquals(
    "users should have different emails",
    secondUserEmail,
    firstUserEmail,
  );
  TestValidator.notEquals(
    "users should have different IDs",
    secondUser.id,
    firstUser.id,
  );

  // Attempt to delete the task as the second user (should fail due to ownership)
  await TestValidator.error(
    "second user should not be able to delete first user's task - ownership boundaries enforced",
    async () => {
      await api.functional.todoApp.user.tasks.erase(connection, {
        taskId: firstUserTask.id,
      });
    },
  );

  // Verify second user can create their own task (proves authentication works)
  const secondUserTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Second user task",
        description: "Task created by second user to verify authentication",
        priority: "Low",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(secondUserTask);

  // Verify second user cannot delete their own task (different from first user's task)
  TestValidator.notEquals(
    "second user task should have different ID",
    secondUserTask.id,
    firstUserTask.id,
  );
  TestValidator.equals(
    "second user task should belong to second user",
    secondUserTask.user.id,
    secondUser.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test deleting a task that belongs to a category.
 *
 * This comprehensive test validates the complete lifecycle of a categorized
 * task, from user registration through task deletion. The test ensures that
 * category relationships are properly handled during task deletion and that
 * category integrity is maintained throughout the process.
 *
 * Test workflow:
 *
 * 1. Create a new user account to establish authentication context
 * 2. Create a task category for organizing tasks
 * 3. Create a task and assign it to the created category
 * 4. Verify the task is properly associated with the category
 * 5. Delete the task and confirm successful deletion
 * 6. Validate that the category remains intact after task deletion
 * 7. Test error cases for task deletion scenarios
 */
export async function test_api_task_delete_with_category(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePass123",
      href: "https://example.com/todo",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create a task category for organization
  const category = await api.functional.todoApp.user.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 8,
        }),
        description: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 5,
          wordMax: 10,
        }),
      } satisfies ITodoAppCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Create multiple tasks and assign them to the category
  const task1 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 1,
        wordMin: 3,
        wordMax: 6,
      }),
      description: RandomGenerator.paragraph({
        sentences: 2,
        wordMin: 4,
        wordMax: 8,
      }),
      todo_app_category_id: category.id,
      priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
      due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task1);

  const task2 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 1,
        wordMin: 3,
        wordMax: 6,
      }),
      description: RandomGenerator.paragraph({
        sentences: 2,
        wordMin: 4,
        wordMax: 8,
      }),
      todo_app_category_id: category.id,
      priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task2);

  // Step 4: Validate the tasks are properly associated with the category
  TestValidator.equals(
    "task1 has category association",
    task1.category?.id,
    category.id,
  );
  TestValidator.equals(
    "task2 has category association",
    task2.category?.id,
    category.id,
  );
  TestValidator.equals(
    "task1 category name matches",
    task1.category?.name,
    category.name,
  );
  TestValidator.equals(
    "task2 category name matches",
    task2.category?.name,
    category.name,
  );

  // Step 5: Delete the first task
  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: task1.id,
  });

  // Step 6: Verify the category remains intact and the second task still exists
  // We validate this by creating a new task with the same category
  const newTask = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 1,
        wordMin: 3,
        wordMax: 6,
      }),
      description: RandomGenerator.paragraph({
        sentences: 2,
        wordMin: 4,
        wordMax: 8,
      }),
      todo_app_category_id: category.id,
      priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(newTask);

  // Validate that the new task can use the same category, proving category integrity
  TestValidator.equals(
    "new task can use same category",
    newTask.category?.id,
    category.id,
  );
  TestValidator.equals(
    "category remains available for new tasks",
    newTask.category?.name,
    category.name,
  );

  // Step 7: Test error handling for task deletion
  // Attempt to delete the same task again (should handle gracefully as it's already deleted)
  await TestValidator.error(
    "deleting non-existent task should fail",
    async () => {
      await api.functional.todoApp.user.tasks.erase(connection, {
        taskId: task1.id,
      });
    },
  );

  // Delete the remaining tasks to clean up
  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: task2.id,
  });

  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: newTask.id,
  });

  // Final validation: category should still be available for future tasks
  const finalTask = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: "Final test task",
      todo_app_category_id: category.id,
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(finalTask);

  TestValidator.equals(
    "category persists after all task deletions",
    finalTask.category?.id,
    category.id,
  );
  TestValidator.equals(
    "final task uses same category",
    finalTask.category?.name,
    category.name,
  );

  // Clean up final task
  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: finalTask.id,
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskCompletion } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletion";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful bulk completion of multiple tasks by an authenticated user.
 *
 * This test validates the complete bulk task completion workflow for an
 * authenticated user. The test follows these steps:
 *
 * 1. User registration to establish authentication context
 * 2. Creation of multiple individual tasks (minimum 3 for meaningful testing)
 * 3. Bulk completion operation to mark all tasks as completed simultaneously
 * 4. Validation of response statistics and completion confirmation
 *
 * The bulk completion operation should:
 *
 * - Successfully mark all provided task IDs as completed
 * - Create completion records for each task
 * - Return accurate statistics including successful completion count
 * - Provide meaningful completion percentage and processing time
 * - Handle the operation atomically (all or nothing)
 */
export async function test_api_task_bulk_complete_multiple_tasks_success(
  connection: api.IConnection,
) {
  // Step 1: User registration to establish authentication
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "TestPassword123",
      ip: "127.0.0.1",
      href: "https://example.com/register",
      referrer: "https://example.com/home",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create multiple tasks for bulk completion testing
  const taskCreationPromises = ArrayUtil.repeat(5, async (index) => {
    const taskData = {
      title: `Task ${index + 1}: ${RandomGenerator.paragraph({ sentences: 3 })}`,
      description: RandomGenerator.paragraph({ sentences: 5 }),
      priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
      due_date: new Date(Date.now() + (index + 1) * 86400000).toISOString(), // Future dates
      completion_order: index + 1,
    } satisfies ITodoAppTask.ICreate;

    return await api.functional.todoApp.user.tasks.create(connection, {
      body: taskData,
    });
  });

  const createdTasks = await Promise.all(taskCreationPromises);
  createdTasks.forEach((task) => typia.assert(task));

  // Step 3: Prepare bulk completion request with all task IDs
  const taskIdsForBulkCompletion = createdTasks.map((task) => task.id);

  // Step 4: Execute bulk completion operation
  const bulkCompletionResponse =
    await api.functional.todoApp.user.tasks.bulk_complete.bulkComplete(
      connection,
      {
        body: {
          task_ids: taskIdsForBulkCompletion,
        } satisfies ITodoAppTaskCompletion.ICreate,
      },
    );

  typia.assert(bulkCompletionResponse);

  // Step 5: Validate bulk completion results
  TestValidator.equals(
    "all tasks should be successfully completed",
    bulkCompletionResponse.successfully_completed,
    createdTasks.length,
  );

  TestValidator.equals(
    "no tasks should fail during bulk completion",
    bulkCompletionResponse.failed_count,
    0,
  );

  TestValidator.equals(
    "no tasks should be skipped during bulk completion",
    bulkCompletionResponse.skipped_count,
    0,
  );

  TestValidator.equals(
    "completion percentage should be 100%",
    bulkCompletionResponse.completion_percentage,
    100,
  );

  TestValidator.equals(
    "total requested count should match created tasks count",
    bulkCompletionResponse.total_requested,
    createdTasks.length,
  );

  TestValidator.predicate(
    "completed task IDs contain all originally created task IDs",
    bulkCompletionResponse.completed_task_ids.length ===
      taskIdsForBulkCompletion.length &&
      bulkCompletionResponse.completed_task_ids.every((id) =>
        taskIdsForBulkCompletion.includes(id),
      ),
  );

  TestValidator.predicate(
    "failed task IDs array should be empty",
    bulkCompletionResponse.failed_task_ids.length === 0,
  );

  TestValidator.predicate(
    "processing time should be reasonable (less than 5 seconds)",
    bulkCompletionResponse.processing_time_ms < 5000,
  );

  TestValidator.predicate(
    "response should include meaningful completion message",
    bulkCompletionResponse.message.length > 0,
  );

  TestValidator.predicate(
    "timestamp should be recent (within last minute)",
    new Date().getTime() -
      new Date(bulkCompletionResponse.timestamp).getTime() <
      60000,
  );
}

