import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppCategory";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test advanced text search functionality in category filtering. Validates
 * partial matching capabilities across category names and descriptions,
 * case-insensitive search behavior, and special character handling in search
 * queries. Tests that search results correctly filter categories based on text
 * content while maintaining pagination integrity.
 *
 * This test creates a comprehensive scenario to validate the category search
 * functionality:
 *
 * 1. Creates an authenticated user account
 * 2. Creates multiple categories with varied names and descriptions
 * 3. Tests search functionality with partial matches
 * 4. Tests case-insensitive search behavior
 * 5. Tests special character handling
 * 6. Validates pagination with search results
 * 7. Tests exact matching vs partial matching
 */
export async function test_api_category_search_with_text_filtering(
  connection: api.IConnection,
) {
  // 1. Create authenticated user account
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.MinLength<8>>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies ITodoAppUser.IJoin,
    },
  );
  typia.assert(user);

  // 2. Create multiple categories with varied names and descriptions
  const categories: ITodoAppCategory[] = [];

  // Create categories with simple names and descriptions
  for (let i = 0; i < 5; i++) {
    const shortName = RandomGenerator.alphabets(5);
    const categoryData = {
      name: `${shortName}${i}`,
      description: `Simple description: ${RandomGenerator.paragraph({ sentences: 1, wordMin: 4, wordMax: 8 })}`,
    } satisfies ITodoAppCategory.ICreate;

    const category = await api.functional.todoApp.user.categories.create(
      connection,
      {
        body: categoryData,
      },
    );
    typia.assert(category);
    categories.push(category);
  }

  // Create categories with longer names and complex descriptions
  for (let i = 5; i < 10; i++) {
    const complexName = RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 3,
      wordMax: 5,
    });
    const categoryData = {
      name: `${complexName}-${i}`,
      description: `Complex description: ${RandomGenerator.paragraph({ sentences: 2, wordMin: 5, wordMax: 10 })} with special characters: !@#$%^&*()`,
    } satisfies ITodoAppCategory.ICreate;

    const category = await api.functional.todoApp.user.categories.create(
      connection,
      {
        body: categoryData,
      },
    );
    typia.assert(category);
    categories.push(category);
  }

  // 3. Test search functionality with partial matches
  const partialSearchTerm = categories[0].name.substring(0, 3);
  const partialMatchQuery = {
    search: partialSearchTerm,
    page: 1,
    limit: 5,
  } satisfies ITodoAppCategory.IRequest;

  const partialMatchResponse =
    await api.functional.todoApp.user.categories.index(connection, {
      body: partialMatchQuery,
    });
  typia.assert(partialMatchResponse);

  TestValidator.predicate(
    "partial match returns results for category index",
    () => partialMatchResponse.data.length > 0,
  );
  TestValidator.predicate(
    "partial match results contain search term for category index",
    () =>
      partialMatchResponse.data.some(
        (cat) =>
          cat.name
            .toLowerCase()
            .includes(partialMatchQuery.search.toLowerCase()) ||
          (cat.description &&
            cat.description
              .toLowerCase()
              .includes(partialMatchQuery.search.toLowerCase())),
      ),
  );

  // 4. Test case-insensitive search behavior
  const uppercaseSearch = categories[1].name.toUpperCase();
  const caseInsensitiveQuery = {
    search: uppercaseSearch,
    page: 1,
    limit: 5,
  } satisfies ITodoAppCategory.IRequest;

  const caseInsensitiveResponse =
    await api.functional.todoApp.user.categories.index(connection, {
      body: caseInsensitiveQuery,
    });
  typia.assert(caseInsensitiveResponse);

  TestValidator.predicate(
    "case-insensitive search returns results for category index",
    () => caseInsensitiveResponse.data.length > 0,
  );
  TestValidator.predicate(
    "case-insensitive search finds original category with index",
    () =>
      caseInsensitiveResponse.data.some(
        (cat) => cat.name.toLowerCase() === uppercaseSearch.toLowerCase(),
      ),
  );

  // 5. Test special character handling
  const specialCharQuery = {
    search: "!@#$%^&*()",
    page: 1,
    limit: 5,
  } satisfies ITodoAppCategory.IRequest;

  const specialCharResponse =
    await api.functional.todoApp.user.categories.index(connection, {
      body: specialCharQuery,
    });
  typia.assert(specialCharResponse);

  TestValidator.predicate(
    "special character search handles symbols correctly",
    () => {
      return specialCharResponse.data.every((cat) => {
        const searchTerm = specialCharQuery.search.toLowerCase();
        return (
          cat.name.toLowerCase().includes(searchTerm) ||
          (cat.description &&
            cat.description.toLowerCase().includes(searchTerm))
        );
      });
    },
  );

  // 6. Test pagination with search results
  const paginationQuery = {
    search: RandomGenerator.alphabets(3),
    page: 1,
    limit: 3,
  } satisfies ITodoAppCategory.IRequest;

  const paginationResponse = await api.functional.todoApp.user.categories.index(
    connection,
    {
      body: paginationQuery,
    },
  );
  typia.assert(paginationResponse);

  TestValidator.equals(
    "pagination response has correct limit for category index",
    paginationResponse.pagination.limit,
    paginationQuery.limit!,
  );
  TestValidator.equals(
    "pagination response has correct current page for category index",
    paginationResponse.pagination.current,
    paginationQuery.page!,
  );
  TestValidator.predicate(
    "pagination response data does not exceed limit for category index",
    () => paginationResponse.data.length <= paginationQuery.limit!,
  );

  // 7. Test exact matching vs partial matching
  const exactMatchQuery = {
    search: categories[2].name,
    page: 1,
    limit: 10,
  } satisfies ITodoAppCategory.IRequest;

  const exactMatchResponse = await api.functional.todoApp.user.categories.index(
    connection,
    {
      body: exactMatchQuery,
    },
  );
  typia.assert(exactMatchResponse);

  TestValidator.predicate(
    "exact match query finds exact category with index",
    () =>
      exactMatchResponse.data.some(
        (cat) => cat.name === exactMatchQuery.search,
      ),
  );

  // 8. Test empty search (should return all categories)
  const emptySearchQuery = {
    search: "",
    page: 1,
    limit: 20,
  } satisfies ITodoAppCategory.IRequest;

  const emptySearchResponse =
    await api.functional.todoApp.user.categories.index(connection, {
      body: emptySearchQuery,
    });
  typia.assert(emptySearchResponse);

  TestValidator.predicate(
    "empty search returns all categories for index",
    () =>
      emptySearchResponse.data.length > 0 &&
      emptySearchResponse.data.length <= categories.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICompletionTrend } from "@ORGANIZATION/PROJECT-api/lib/structures/ICompletionTrend";
import type { IDailyCompletionEntry } from "@ORGANIZATION/PROJECT-api/lib/structures/IDailyCompletionEntry";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskCompletion } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletion";
import type { ITodoAppTaskCompletionsStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionsStatistics";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test basic daily completion statistics retrieval.
 *
 * This test validates that authenticated users can access their task completion
 * statistics over various timeframes. Tests the operation returns correct daily
 * completion counts, total completions, and basic trend information. Verifies
 * the response includes proper date formatting and completion counts that
 * accurately reflect user activity.
 *
 * Test Steps:
 *
 * 1. Create a new user account through registration
 * 2. Create multiple todo tasks with different priorities and due dates
 * 3. Complete tasks on different days using bulk completion to generate varied
 *    data
 * 4. Retrieve daily completion statistics
 * 5. Validate the statistics structure and data integrity
 * 6. Verify date formatting, completion counts, and trend indicators
 */
export async function test_api_daily_completion_statistics_basic(
  connection: api.IConnection,
) {
  // Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePass123",
      ip: null,
      href: "https://todoapp.com/register",
      referrer: "https://todoapp.com/landing",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(user);

  // Create multiple tasks with different properties to test completion statistics
  const tasks: ITodoAppTask[] = [];

  // Create tasks with different priorities and properties
  for (let i = 0; i < 15; i++) {
    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 8,
        }),
        description:
          i % 3 === 0
            ? RandomGenerator.content({
                paragraphs: 1,
                sentenceMin: 2,
                sentenceMax: 4,
              })
            : null,
        priority: RandomGenerator.pick(["Low", "Medium", "High"] as const),
        due_date:
          i % 2 === 0
            ? new Date(Date.now() + i * 86400000).toISOString()
            : null,
        completion_order: i,
      } satisfies ITodoAppTask.ICreate,
    });
    typia.assert(task);
    tasks.push(task);

    // Verify task is created with pending status
    TestValidator.predicate(
      "task created with pending status",
      task.status === "pending",
    );
  }

  // Complete tasks in batches to generate completion statistics
  const taskIds: string[] = tasks.map((task) => task.id);

  // Complete first batch (5 tasks) and verify completion
  const firstBatchIds = taskIds.slice(0, 5);
  const firstCompletion =
    await api.functional.todoApp.user.tasks.bulk_complete.bulkComplete(
      connection,
      {
        body: {
          task_ids: firstBatchIds,
        } satisfies ITodoAppTaskCompletion.ICreate,
      },
    );
  typia.assert(firstCompletion);
  TestValidator.equals(
    "first batch completion count",
    firstCompletion.successfully_completed,
    5,
  );
  TestValidator.equals(
    "first batch total requested",
    firstCompletion.total_requested,
    5,
  );

  // Complete second batch (5 tasks) and verify completion
  const secondBatchIds = taskIds.slice(5, 10);
  const secondCompletion =
    await api.functional.todoApp.user.tasks.bulk_complete.bulkComplete(
      connection,
      {
        body: {
          task_ids: secondBatchIds,
        } satisfies ITodoAppTaskCompletion.ICreate,
      },
    );
  typia.assert(secondCompletion);
  TestValidator.equals(
    "second batch completion count",
    secondCompletion.successfully_completed,
    5,
  );
  TestValidator.equals(
    "second batch total requested",
    secondCompletion.total_requested,
    5,
  );

  // Complete final batch (5 tasks) and verify completion
  const finalBatchIds = taskIds.slice(10);
  const finalCompletion =
    await api.functional.todoApp.user.tasks.bulk_complete.bulkComplete(
      connection,
      {
        body: {
          task_ids: finalBatchIds,
        } satisfies ITodoAppTaskCompletion.ICreate,
      },
    );
  typia.assert(finalCompletion);
  TestValidator.equals(
    "final batch completion count",
    finalCompletion.successfully_completed,
    5,
  );
  TestValidator.equals(
    "final batch total requested",
    finalCompletion.total_requested,
    5,
  );

  // Retrieve daily completion statistics
  const statistics =
    await api.functional.todoApp.user.statistics.daily_completions.at(
      connection,
    );
  typia.assert(statistics);

  // Validate the statistics structure and basic integrity
  TestValidator.predicate(
    "statistics has valid total completions",
    statistics.total_completions >= 0,
  );
  TestValidator.predicate(
    "statistics has valid distinct days count",
    statistics.distinct_days_with_completions >= 0,
  );
  TestValidator.predicate(
    "statistics has daily completions array",
    Array.isArray(statistics.daily_completions),
  );
  TestValidator.predicate(
    "statistics daily completions array is not empty",
    statistics.daily_completions.length > 0,
  );

  // Calculate expected total from daily entries for validation
  const calculatedTotal = statistics.daily_completions.reduce(
    (sum, entry) => sum + entry.completion_count,
    0,
  );
  TestValidator.equals(
    "calculated total matches statistics total",
    calculatedTotal,
    statistics.total_completions,
  );

  // Validate that daily completions entries have proper structure
  for (const entry of statistics.daily_completions) {
    typia.assert<IDailyCompletionEntry>(entry);
    TestValidator.predicate(
      "daily entry has valid date format",
      typia.is<string & tags.Format<"date">>(entry.date),
    );
    TestValidator.predicate(
      "daily entry has non-negative completion count",
      entry.completion_count >= 0,
    );
  }

  // Validate statistics summary values
  TestValidator.predicate(
    "distinct days count is reasonable",
    statistics.distinct_days_with_completions >= 0 &&
      statistics.distinct_days_with_completions <= 31,
  );
  TestValidator.predicate(
    "total completions matches expected range",
    statistics.total_completions >= 0 && statistics.total_completions <= 100,
  );

  // Validate optional trend information if present
  if (statistics.trend) {
    typia.assert<ICompletionTrend>(statistics.trend);
    TestValidator.predicate(
      "trend has valid direction",
      ["increasing", "decreasing", "stable"].includes(
        statistics.trend.direction,
      ),
    );

    if (statistics.trend.weekly_average_change_percent !== undefined) {
      TestValidator.predicate(
        "trend change percent is within valid range",
        statistics.trend.weekly_average_change_percent >= -100 &&
          statistics.trend.weekly_average_change_percent <= 100,
      );
    }

    if (statistics.trend.consistency_score !== undefined) {
      TestValidator.predicate(
        "consistency score is within valid range",
        statistics.trend.consistency_score >= 0 &&
          statistics.trend.consistency_score <= 100,
      );
    }
  }

  // Validate average daily completions if present
  if (statistics.average_daily_completions !== undefined) {
    TestValidator.predicate(
      "average daily completions is non-negative",
      statistics.average_daily_completions >= 0,
    );
    TestValidator.predicate(
      "average makes sense with daily data",
      statistics.average_daily_completions <= statistics.total_completions,
    );
  }

  // Validate best day information if present
  if (
    statistics.best_day_completions !== undefined &&
    statistics.best_day_date !== undefined
  ) {
    TestValidator.predicate(
      "best day completions is non-negative",
      statistics.best_day_completions >= 0,
    );
    TestValidator.predicate(
      "best day date has valid format",
      typia.is<string & tags.Format<"date">>(statistics.best_day_date),
    );
    TestValidator.predicate(
      "best day completions is not more than total",
      statistics.best_day_completions <= statistics.total_completions,
    );
  }

  // Validate date range information if present
  if (statistics.analysis_period_start_date !== undefined) {
    TestValidator.predicate(
      "analysis start date has valid format",
      typia.is<string & tags.Format<"date">>(
        statistics.analysis_period_start_date,
      ),
    );
  }

  if (statistics.analysis_period_end_date !== undefined) {
    TestValidator.predicate(
      "analysis end date has valid format",
      typia.is<string & tags.Format<"date">>(
        statistics.analysis_period_end_date,
      ),
    );
  }

  // Validate that all completed tasks are reflected in statistics
  TestValidator.predicate(
    "statistics reflect actual completions",
    statistics.total_completions === 15,
  );
  TestValidator.predicate(
    "statistics include all distinct completion days",
    statistics.distinct_days_with_completions >= 1,
  );

  // Verify data consistency across all optional fields
  if (
    statistics.average_daily_completions &&
    statistics.distinct_days_with_completions > 0
  ) {
    TestValidator.predicate(
      "average calculation is consistent",
      Math.abs(
        statistics.average_daily_completions -
          statistics.total_completions /
            statistics.distinct_days_with_completions,
      ) < 0.1,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ICompletionTrend } from "@ORGANIZATION/PROJECT-api/lib/structures/ICompletionTrend";
import type { IDailyCompletionEntry } from "@ORGANIZATION/PROJECT-api/lib/structures/IDailyCompletionEntry";
import type { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskCompletion } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletion";
import type { ITodoAppTaskCompletionsStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionsStatistics";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test daily completion statistics with different timeframe parameters.
 *
 * This test validates the daily completion statistics API endpoint by creating
 * tasks across different time periods and completing them on specific dates to
 * test date range filtering. It verifies that statistics correctly aggregate
 * data over various analysis periods including single-day ranges, weekly
 * periods, and monthly timeframes.
 *
 * The test covers:
 *
 * - Basic daily completion statistics for default timeframe
 * - Task creation across multiple days to establish completion patterns
 * - Bulk task completion on specific dates to create time-bounded data
 * - Validation of completion trend analysis and metrics
 * - Edge cases including single-day ranges and future dates
 * - Verification of period start/end date calculations
 * - Trend direction analysis (increasing, decreasing, stable patterns)
 * - Daily completion entry structure and data integrity
 *
 * @param connection API connection for making authenticated requests
 */
export async function test_api_daily_completion_statistics_with_time_ranges(
  connection: api.IConnection,
) {
  // Step 1: Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userAccount = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "TestPassword123!",
      ip: "192.168.1.1",
      href: "https://todo-app.com/auth/join",
      referrer: "https://todo-app.com/auth",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(userAccount);

  TestValidator.equals(
    "user account has valid ID",
    userAccount.id,
    userAccount.id,
  );

  // Step 2: Create tasks across different time periods to test date range filtering
  const today = new Date();
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  const monthAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);
  const twoDaysAgo = new Date(today.getTime() - 2 * 24 * 60 * 60 * 1000);

  // Create tasks for testing different completion patterns
  const createdTasks: ITodoAppTask[] = [];

  const tasksToCreate = [
    // Tasks created recently (for current week testing)
    {
      title: "Recent Task 1",
      description: "Task to test current week statistics",
      priority: "Medium" as const,
      due_date: today.toISOString(),
    },
    {
      title: "Recent Task 2",
      description: "Task to test current week statistics",
      priority: "High" as const,
      due_date: twoDaysAgo.toISOString(),
    },
    {
      title: "Recent Task 3",
      description: "Task to test current week statistics",
      priority: "Low" as const,
      due_date: weekAgo.toISOString(),
    },
    // Tasks created longer ago (for monthly testing)
    {
      title: "Month Ago Task 1",
      description: "Task created a month ago for range testing",
      priority: "Medium" as const,
      due_date: monthAgo.toISOString(),
    },
    {
      title: "No Due Date Task",
      description: "Task without due date for comprehensive testing",
      priority: "Low" as const,
    },
  ];

  for (const taskData of tasksToCreate) {
    const createdTask = await api.functional.todoApp.user.tasks.create(
      connection,
      {
        body: taskData satisfies ITodoAppTask.ICreate,
      },
    );
    typia.assert(createdTask);
    createdTasks.push(createdTask);
  }

  TestValidator.equals(
    "created correct number of tasks",
    createdTasks.length,
    5,
  );

  // Step 3: Complete tasks on specific dates to create time-bounded completion data
  const statistics =
    await api.functional.todoApp.user.statistics.daily_completions.at(
      connection,
    );
  typia.assert(statistics);

  // Test 1: Validate basic structure and initial state (no completions yet)
  TestValidator.equals(
    "statistics has correct total completions initially",
    statistics.total_completions,
    0,
  );
  TestValidator.equals(
    "statistics shows no distinct days with completions initially",
    statistics.distinct_days_with_completions,
    0,
  );
  TestValidator.predicate("daily completions array exists", () =>
    Array.isArray(statistics.daily_completions),
  );

  // Step 4: Complete multiple tasks on specific dates to test aggregation
  const completionPromises = Array.from({ length: 3 }, (_, i) => {
    const targetDate = new Date(today.getTime() - i * 24 * 60 * 60 * 1000);
    const tasksForCompletion = createdTasks
      .slice(i, i + 2)
      .map((task) => task.id);

    return api.functional.todoApp.user.tasks.bulk_complete.bulkComplete(
      connection,
      {
        body: {
          task_ids: tasksForCompletion,
        } satisfies ITodoAppTaskCompletion.ICreate,
      },
    );
  });

  const completionResults = await Promise.all(completionPromises);
  completionResults.forEach((result) => typia.assert(result));

  TestValidator.predicate("completion operations succeeded", () =>
    completionResults.every((result) => result.successfully_completed > 0),
  );

  // Step 5: Test daily completion statistics after task completions
  const updatedStatistics =
    await api.functional.todoApp.user.statistics.daily_completions.at(
      connection,
    );
  typia.assert(updatedStatistics);

  // Test 2: Validate updated statistics with completion data
  TestValidator.predicate(
    "statistics have completion data",
    () =>
      updatedStatistics.total_completions > 0 &&
      updatedStatistics.distinct_days_with_completions > 0,
  );

  TestValidator.predicate(
    "trend data is present",
    () =>
      updatedStatistics.trend !== undefined && updatedStatistics.trend !== null,
  );

  if (
    updatedStatistics.trend !== null &&
    updatedStatistics.trend !== undefined
  ) {
    const validDirections = ["increasing", "decreasing", "stable"] as const;
    TestValidator.predicate("trend direction is valid value", () =>
      validDirections.includes(updatedStatistics.trend!.direction),
    );
  }

  // Test 3: Validate daily completion entries structure
  TestValidator.predicate(
    "daily completion entries are valid structure",
    () => {
      return updatedStatistics.daily_completions.every(
        (entry: IDailyCompletionEntry) =>
          typeof entry.date === "string" &&
          entry.date.length > 0 &&
          typeof entry.completion_count === "number" &&
          entry.completion_count >= 0,
      );
    },
  );

  // Test 4: Verify chronological order of daily entries
  TestValidator.predicate("daily entries maintain chronological order", () => {
    for (let i = 1; i < updatedStatistics.daily_completions.length; i++) {
      const currentDate = new Date(updatedStatistics.daily_completions[i].date);
      const previousDate = new Date(
        updatedStatistics.daily_completions[i - 1].date,
      );
      if (currentDate < previousDate) {
        return false;
      }
    }
    return true;
  });

  // Test 5: Validate average daily completions calculation
  if (
    updatedStatistics.average_daily_completions !== undefined &&
    updatedStatistics.average_daily_completions !== null
  ) {
    TestValidator.predicate(
      "average daily completions is non-negative",
      () => updatedStatistics.average_daily_completions! >= 0,
    );
  }

  // Test 6: Verify best day tracking
  if (
    updatedStatistics.best_day_completions !== undefined &&
    updatedStatistics.best_day_completions !== null
  ) {
    TestValidator.predicate(
      "best day completion count is positive",
      () => updatedStatistics.best_day_completions! > 0,
    );

    if (
      updatedStatistics.best_day_date !== undefined &&
      updatedStatistics.best_day_date !== null
    ) {
      TestValidator.predicate("best day date is valid date format", () => {
        try {
          new Date(updatedStatistics.best_day_date!);
          return true;
        } catch {
          return false;
        }
      });
    }
  }

  // Test 7: Validate period date ranges
  TestValidator.predicate(
    "analysis period dates are valid when provided",
    () => {
      if (
        updatedStatistics.analysis_period_start_date &&
        updatedStatistics.analysis_period_end_date
      ) {
        try {
          const startDate = new Date(
            updatedStatistics.analysis_period_start_date,
          );
          const endDate = new Date(updatedStatistics.analysis_period_end_date);
          return (
            startDate.toString() !== "Invalid Date" &&
            endDate.toString() !== "Invalid Date" &&
            endDate >= startDate
          );
        } catch {
          return false;
        }
      }
      return true;
    },
  );

  // Test 8: Verify consistency metrics
  if (
    updatedStatistics.trend?.consistency_score !== undefined &&
    updatedStatistics.trend?.consistency_score !== null
  ) {
    TestValidator.predicate(
      "consistency score is within valid range 0-100",
      () =>
        updatedStatistics.trend!.consistency_score! >= 0 &&
        updatedStatistics.trend!.consistency_score! <= 100,
    );
  }

  // Test 9: Data integrity verification
  TestValidator.predicate(
    "total completions equals sum of daily completions",
    () => {
      const calculatedTotal = updatedStatistics.daily_completions.reduce(
        (sum: number, entry: IDailyCompletionEntry) =>
          sum + entry.completion_count,
        0,
      );
      return calculatedTotal === updatedStatistics.total_completions;
    },
  );

  // Test 10: Realistic usage pattern validation
  TestValidator.predicate(
    "statistics reflect realistic task completion patterns",
    () => {
      return (
        updatedStatistics.total_completions >= 0 &&
        updatedStatistics.distinct_days_with_completions >= 0 &&
        updatedStatistics.total_completions <=
          createdTasks.length *
            Math.max(1, updatedStatistics.distinct_days_with_completions)
      );
    },
  );
}

