import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppDashboard } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppDashboard";
import { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";

export async function getTodoAppDashboardOverview(): Promise<ITodoAppDashboard.IOverview> {
  const now = new Date();
  const today = toISOStringSafe(
    new Date(now.getFullYear(), now.getMonth(), now.getDate()),
  );
  const weekFromNow = toISOStringSafe(
    new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
  );
  const weekStart = toISOStringSafe(
    new Date(now.getTime() - now.getDay() * 24 * 60 * 60 * 1000),
  );
  const monthStart = toISOStringSafe(
    new Date(now.getFullYear(), now.getMonth(), 1),
  );
  const tomorrow = toISOStringSafe(
    new Date(now.getTime() + 24 * 60 * 60 * 1000),
  );

  // Get category data first to build lookup map
  const categories = await MyGlobal.prisma.todo_app_categories.findMany();
  const categoryMap = new Map(categories.map((cat) => [cat.id, cat]));

  // Calculate core task statistics
  const allTasks = await MyGlobal.prisma.todo_app_tasks.findMany({
    include: { category: true },
  });

  const completedTasksList =
    await MyGlobal.prisma.todo_app_task_completions.findMany({
      include: { task: { include: { category: true } } },
      orderBy: { completed_at: "desc" },
      take: 10,
    });

  // Calculate task counts
  let activeTasks = 0;
  let completedTasks = 0;
  let pendingTasks = 0;
  let inProgressTasks = 0;
  let highPriorityTasks = 0;
  let mediumPriorityTasks = 0;
  let lowPriorityTasks = 0;
  let tasksWithDueDate = 0;
  let overdueTasks = 0;
  let todayDueTasks = 0;
  let weekDueTasks = 0;

  const categoryStats = new Map<
    string,
    { active: number; completed: number; total: number }
  >();

  // Process all tasks
  for (const task of allTasks) {
    // Status counts
    if (task.status === "completed") {
      completedTasks++;
    } else if (task.status === "pending") {
      pendingTasks++;
      activeTasks++;
    } else if (task.status === "in-progress") {
      inProgressTasks++;
      activeTasks++;
    }

    // Priority counts
    if (task.priority === "High") {
      highPriorityTasks++;
    } else if (task.priority === "Medium") {
      mediumPriorityTasks++;
    } else {
      lowPriorityTasks++;
    }

    // Due date analysis
    if (task.due_date) {
      tasksWithDueDate++;
      const dueDate = new Date(task.due_date);
      const taskStatus = task.status;

      if (taskStatus !== "completed" && dueDate < now) {
        overdueTasks++;
      }

      if (
        taskStatus !== "completed" &&
        dueDate >= new Date(today) &&
        dueDate < new Date(tomorrow)
      ) {
        todayDueTasks++;
      }

      if (
        taskStatus !== "completed" &&
        dueDate >= new Date(today) &&
        dueDate <= new Date(weekFromNow)
      ) {
        weekDueTasks++;
      }
    }

    // Category statistics
    if (task.category) {
      const stats = categoryStats.get(task.category.id) || {
        active: 0,
        completed: 0,
        total: 0,
      };
      stats.total++;

      if (task.status === "completed") {
        stats.completed++;
      } else {
        stats.active++;
      }

      categoryStats.set(task.category.id, stats);
    }
  }

  const totalTasks = allTasks.length;
  const overallCompletionRate =
    totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  // Calculate time-based completion rates
  const weekStartDate = new Date(weekStart);
  const monthStartDate = new Date(monthStart);

  const thisWeekCompleted = completedTasksList.filter(
    (comp) => new Date(comp.completed_at) >= weekStartDate,
  ).length;

  const thisMonthCompleted = completedTasksList.filter(
    (comp) => new Date(comp.completed_at) >= monthStartDate,
  ).length;

  const thisWeekCreated = allTasks.filter(
    (task) => new Date(task.created_at) >= weekStartDate,
  ).length;

  const thisMonthCreated = allTasks.filter(
    (task) => new Date(task.created_at) >= monthStartDate,
  ).length;

  const thisWeekCompletionRate =
    thisWeekCreated > 0
      ? (thisWeekCompleted / (thisWeekCreated + completedTasks)) * 100
      : 0;
  const thisMonthCompletionRate =
    thisMonthCreated > 0
      ? (thisMonthCompleted / (thisMonthCreated + completedTasks)) * 100
      : 0;

  // Calculate average time to completion
  const completionSummaries = completedTasksList
    .slice(0, 50)
    .filter((comp) => comp.completed_at && comp.task.created_at);

  const averageTimeToCompletion =
    completionSummaries.length > 0
      ? completionSummaries.reduce((sum, comp) => {
          const hours =
            (new Date(comp.completed_at).getTime() -
              new Date(comp.task.created_at).getTime()) /
            (1000 * 60 * 60);
          return sum + Math.max(0, hours);
        }, 0) /
        completionSummaries.length /
        24
      : undefined;

  // Build category counts
  const categoryCounts: ITodoAppDashboard.ICategoryCount[] = Array.from(
    categoryStats.entries(),
  ).map(([categoryId, stats]) => {
    const category = categoryMap.get(categoryId)!;
    const completionRate =
      stats.total > 0 ? (stats.completed / stats.total) * 100 : 0;

    return {
      category: {
        id: category.id as string & tags.Format<"uuid">,
        name: category.name,
        description: category.description,
        created_at: toISOStringSafe(category.created_at),
        updated_at: toISOStringSafe(category.updated_at),
      },
      active_tasks_count: stats.active,
      completed_tasks_count: stats.completed,
      completion_rate: Math.round(completionRate * 100) / 100,
    };
  });

  // Build recent completions
  const recentCompletions: ITodoAppDashboard.IRecentCompletion[] =
    completedTasksList.map((completion) => {
      const hours =
        (new Date(completion.completed_at).getTime() -
          new Date(completion.task.created_at).getTime()) /
        (1000 * 60 * 60);

      return {
        id: completion.id as string & tags.Format<"uuid">,
        task_id: completion.todo_app_task_id as string & tags.Format<"uuid">,
        title: completion.task.title,
        category: completion.task.category
          ? {
              id: completion.task.category.id as string & tags.Format<"uuid">,
              name: completion.task.category.name,
              description: completion.task.category.description,
              created_at: toISOStringSafe(completion.task.category.created_at),
              updated_at: toISOStringSafe(completion.task.category.updated_at),
            }
          : null,
        priority: completion.task.priority as "Low" | "Medium" | "High",
        completed_at: toISOStringSafe(completion.completed_at),
        time_to_completion_hours: Math.round(Math.max(0, hours)),
      };
    });

  return {
    active_tasks_count: activeTasks,
    completed_tasks_count: completedTasks,
    pending_tasks_count: pendingTasks,
    in_progress_tasks_count: inProgressTasks,
    high_priority_tasks_count: highPriorityTasks,
    medium_priority_tasks_count: mediumPriorityTasks,
    low_priority_tasks_count: lowPriorityTasks,
    tasks_with_due_date_count: tasksWithDueDate,
    overdue_tasks_count: overdueTasks,
    today_due_tasks_count: todayDueTasks,
    week_due_tasks_count: weekDueTasks,
    task_completion_rate: Math.round(overallCompletionRate * 100) / 100,
    this_week_completion_rate: Math.round(thisWeekCompletionRate * 100) / 100,
    this_month_completion_rate: Math.round(thisMonthCompletionRate * 100) / 100,
    average_time_to_completion_days: averageTimeToCompletion
      ? Math.round(averageTimeToCompletion * 100) / 100
      : undefined,
    category_counts: categoryCounts,
    recent_completions: recentCompletions,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserTasksTaskId(props: {
  user: UserPayload;
  taskId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTask> {
  // Fetch task with user and category relationships
  const task = await MyGlobal.prisma.todo_app_tasks.findUnique({
    where: { id: props.taskId },
    include: {
      user: true,
      category: true,
    },
  });

  if (!task) {
    throw new HttpException("Task not found", 404);
  }

  // Authorization check - ensure user owns the task
  if (task.todo_app_user_id !== props.user.id) {
    throw new HttpException(
      "You don't have permission to access this task",
      403,
    );
  }

  return {
    id: task.id,
    title: task.title,
    description: task.description,
    status: typia.assert<"pending" | "in-progress" | "completed">(task.status),
    priority: typia.assert<"Low" | "Medium" | "High">(task.priority),
    due_date: task.due_date ? toISOStringSafe(task.due_date) : null,
    completion_order: task.completion_order,
    created_at: toISOStringSafe(task.created_at),
    updated_at: toISOStringSafe(task.updated_at),
    user: {
      id: task.user.id,
      email: task.user.email,
      created_at: toISOStringSafe(task.user.created_at),
      updated_at: toISOStringSafe(task.user.updated_at),
      deleted_at: task.user.deleted_at
        ? toISOStringSafe(task.user.deleted_at)
        : undefined,
    },
    category: task.category
      ? {
          id: task.category.id,
          name: task.category.name,
          description: task.category.description,
          created_at: toISOStringSafe(task.category.created_at),
          updated_at: toISOStringSafe(task.category.updated_at),
        }
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskDeletion } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskDeletion";
import { ITodoAppTaskId } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskId";
import { IError } from "@ORGANIZATION/PROJECT-api/lib/structures/IError";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTasksBulkDelete(props: {
  user: UserPayload;
  body: ITodoAppTaskDeletion.ICreate;
}): Promise<ITodoAppTaskDeletion.ISummary> {
  const taskIds = props.body.task_ids.map((task) => task.id);

  // First, check ownership and existence of all tasks
  const existingTasks = await MyGlobal.prisma.todo_app_tasks.findMany({
    where: {
      id: {
        in: taskIds,
      },
    },
    select: {
      id: true,
      todo_app_user_id: true,
    },
  });

  // Build error summary
  const errors: IError.ISummary[] = [];
  const validTaskIds: string[] = [];

  // Check each task for issues
  for (const taskId of taskIds) {
    const task = existingTasks.find((t) => t.id === taskId);

    if (!task) {
      errors.push({
        code: "TASK_NOT_FOUND",
        message: "Task not found",
        task_id: taskId,
      });
    } else if (task.todo_app_user_id !== props.user.id) {
      errors.push({
        code: "UNAUTHORIZED",
        message: "Task does not belong to authenticated user",
        task_id: taskId,
      });
    } else {
      validTaskIds.push(taskId);
    }
  }

  // If there are any errors, return with 0 deletions (atomic operation)
  if (errors.length > 0) {
    return {
      deleted_count: 0,
      total_requested: taskIds.length satisfies number as number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      errors,
    };
  }

  // Perform bulk deletion atomically
  const result = await MyGlobal.prisma.todo_app_tasks.deleteMany({
    where: {
      id: {
        in: validTaskIds,
      },
    },
  });

  return {
    deleted_count: result.count satisfies number as number as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    total_requested: taskIds.length satisfies number as number as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    errors: [],
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserLimit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserLimit";
import { IPaginationBase } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaginationBase";
import { ISortOption } from "@ORGANIZATION/PROJECT-api/lib/structures/ISortOption";
import { IPageITodoAppUserLimit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppUserLimit";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { ITodoAppValidationRule } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppValidationRule";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserUserLimitsUserUserId(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
  body: ITodoAppUserLimit.IRequest;
}): Promise<IPageITodoAppUserLimit.ISummary> {
  // Security check - users can only access their own limits
  if (props.user.id !== props.userId) {
    throw new HttpException("You can only view your own user limits", 403);
  }

  const { pagination, limitType, periodType, isActive } = props.body;
  const page = pagination.page;
  const limit = pagination.limit;
  const skip = (page - 1) * limit;

  // Build where condition dynamically
  const whereCondition: Record<string, unknown> = {
    user_id: props.userId,
  };

  if (limitType !== undefined && limitType !== null) {
    whereCondition.limit_type = limitType;
  }

  if (periodType !== undefined && periodType !== null) {
    whereCondition.period_type = periodType;
  }

  if (isActive !== undefined && isActive !== null) {
    whereCondition.is_active = isActive;
  }

  // Handle search if provided
  if (pagination.search) {
    whereCondition.description = {
      contains: pagination.search,
    };
  }

  // Apply sorting
  const orderBy: Record<string, "asc" | "desc"> = {};
  if (pagination.sortBy) {
    orderBy[pagination.sortBy.fieldName] = pagination.sortBy.direction;
  } else {
    orderBy.created_at = "desc";
  }

  // Fetch data and total count in parallel
  const [limits, total] = await Promise.all([
    MyGlobal.prisma.todo_app_user_limits.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy,
      include: {
        user: true,
        constraintRule: true,
      },
    }),
    MyGlobal.prisma.todo_app_user_limits.count({
      where: whereCondition,
    }),
  ]);

  // Transform results to API format
  const data = limits.map((limit) => ({
    id: limit.id as string & tags.Format<"uuid">,
    user:
      limit.user !== null && limit.user !== undefined
        ? {
            id: limit.user.id as string & tags.Format<"uuid">,
            email: limit.user.email as string & tags.Format<"email">,
            created_at: toISOStringSafe(limit.user.created_at),
            updated_at: toISOStringSafe(limit.user.updated_at),
            deleted_at: limit.user.deleted_at
              ? toISOStringSafe(limit.user.deleted_at)
              : undefined,
          }
        : undefined,
    constraintRule: limit.constraintRule
      ? {
          id: limit.constraintRule.id as string & tags.Format<"uuid">,
          rule_name: limit.constraintRule.rule_name,
          rule_key: limit.constraintRule.rule_key,
          validation_type: limit.constraintRule.validation_type,
          field_target: limit.constraintRule.field_target || undefined,
          error_message_template:
            limit.constraintRule.error_message_template || undefined,
          priority: limit.constraintRule.priority || undefined,
          is_active: limit.constraintRule.is_active,
          created_at: toISOStringSafe(limit.constraintRule.created_at),
        }
      : undefined,
    limit_value: limit.limit_value as number & tags.Type<"int32">,
    limit_type: limit.limit_type,
    period_type: limit.period_type,
    description: limit.description,
    is_active: limit.is_active,
    created_at: toISOStringSafe(limit.created_at),
    updated_at: toISOStringSafe(limit.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoAppUser.IJoin;
}): Promise<ITodoAppUser.IAuthorized> {
  // Check for duplicate email
  const existing = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });

  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Create user
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const user = await MyGlobal.prisma.todo_app_users.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      email: props.body.email,
      password_hash: hashedPassword,
      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
    },
  });

  // Create session
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      user_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: new Date(),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Generate JWT tokens
  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return authorized user
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoAppUser.ILogin;
}): Promise<ITodoAppUser.IAuthorized> {
  // Find user by email
  const user = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Check if account is deleted (soft delete)
  if (user.deleted_at) {
    throw new HttpException("Account has been deleted", 401);
  }

  // Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Create current timestamp as string
  const now = new Date();

  // Calculate token expiration times
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  // Create new session
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      user_id: user.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Generate JWT tokens - JWT expects seconds since epoch in iat
  const nowSeconds = Math.floor(now.getTime() / 1000);
  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Return authorized user with tokens
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: user.updated_at ? toISOStringSafe(user.updated_at) : undefined,
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  } satisfies ITodoAppUser.IAuthorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoAppUserCategoriesCategoryId(props: {
  user: UserPayload;
  categoryId: string & tags.Format<"uuid">;
  body: ITodoAppCategory.IUpdate;
}): Promise<ITodoAppCategory> {
  // Verify category exists and belongs to user
  const existingCategory = await MyGlobal.prisma.todo_app_categories.findUnique(
    {
      where: { id: props.categoryId },
    },
  );

  if (!existingCategory) {
    throw new HttpException("Category not found", 404);
  }

  if (existingCategory.todo_app_user_id !== props.user.id) {
    throw new HttpException(
      "Forbidden - category does not belong to user",
      403,
    );
  }

  // Build update data with only provided fields
  const updateData: Prisma.todo_app_categoriesUpdateInput = {
    updated_at: new Date(),
  };

  // Handle name update with uniqueness check if provided
  if (props.body.name !== undefined) {
    // Check if another category with this name already exists for this user
    const existingNameCategory =
      await MyGlobal.prisma.todo_app_categories.findFirst({
        where: {
          todo_app_user_id: props.user.id,
          name: props.body.name! satisfies string as string,
          NOT: { id: props.categoryId }, // Exclude current category
        },
      });

    if (existingNameCategory) {
      throw new HttpException("Category name already exists", 409);
    }

    updateData.name = props.body.name! satisfies string as string;
  }

  // Handle description update if provided (can be set to null)
  if (props.body.description !== undefined) {
    updateData.description = props.body.description;
  }

  // Update the category
  const updatedCategory = await MyGlobal.prisma.todo_app_categories.update({
    where: { id: props.categoryId },
    data: updateData,
  });

  // Fetch user summary for response
  const userSummary = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.user.id },
    select: {
      id: true,
      email: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!userSummary) {
    throw new HttpException("User not found", 404);
  }

  return {
    id: updatedCategory.id,
    user: {
      id: userSummary.id,
      email: userSummary.email,
      created_at: toISOStringSafe(userSummary.created_at),
      updated_at: toISOStringSafe(userSummary.updated_at),
      deleted_at: userSummary.deleted_at
        ? toISOStringSafe(userSummary.deleted_at)
        : undefined,
    },
    name: updatedCategory.name,
    description: updatedCategory.description,
    created_at: toISOStringSafe(updatedCategory.created_at),
    updated_at: toISOStringSafe(updatedCategory.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskCompletionRateStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionRateStatistics";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserStatisticsCompletionRate(props: {
  user: UserPayload;
}): Promise<ITodoAppTaskCompletionRateStatistics> {
  const now = new Date();
  const todayISO = toISOStringSafe(now);
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const thirtyDaysAgoISO = toISOStringSafe(thirtyDaysAgo);

  const userId = props.user.id;

  // Get total tasks count (not excluding soft-deleted since deleted_at field doesn't exist)
  const totalTasks = await MyGlobal.prisma.todo_app_tasks.count({
    where: {
      todo_app_user_id: userId,
    },
  });

  if (totalTasks === 0) {
    return {
      total_tasks: 0 as number & tags.Type<"int32"> & tags.Minimum<0>,
      completed_tasks: 0 as number & tags.Type<"int32"> & tags.Minimum<0>,
      incomplete_tasks: 0 as number & tags.Type<"int32"> & tags.Minimum<0>,
      completion_rate_percent: 0 as number &
        tags.Minimum<0> &
        tags.Maximum<100>,
      calculation_date: todayISO,
    };
  }

  // Get completed tasks count
  const completedTasks = await MyGlobal.prisma.todo_app_task_completions.count({
    where: {
      todo_app_user_id: userId,
      reactivated: false,
    },
  });

  const incompleteTasks = totalTasks - completedTasks;
  const completionRatePercent = Math.round((completedTasks / totalTasks) * 100);

  // Get recent completion rate (last 30 days)
  const recentCompletedTasks =
    await MyGlobal.prisma.todo_app_task_completions.count({
      where: {
        todo_app_user_id: userId,
        completed_at: { gte: thirtyDaysAgo },
        reactivated: false,
      },
    });

  // Recent tasks for the period: tasks created before the 30-day end but completed within the period
  // Remove completions filter and just count tasks that were created within recent period
  const recentPeriodTasks = await MyGlobal.prisma.todo_app_tasks.count({
    where: {
      todo_app_user_id: userId,
      created_at: {
        gte: thirtyDaysAgo,
        lte: todayISO,
      },
    },
  });

  let recentCompletionRatePercent: number | undefined;
  if (recentPeriodTasks > 0) {
    recentCompletionRatePercent = Math.round(
      (recentCompletedTasks / recentPeriodTasks) * 100,
    );
  }

  // Calculate streak metrics
  const streakQuery = await MyGlobal.prisma.$queryRaw<
    {
      date: Date;
      completion_count: number;
    }[]
  >`
    SELECT 
      DATE_TRUNC('day', completed_at) as date,
      COUNT(*) as completion_count
    FROM todo_app_task_completions
    WHERE todo_app_user_id = ${userId}::uuid
      AND reactivated = false
      AND completed_at >= NOW() - INTERVAL '31 days'
    GROUP BY DATE_TRUNC('day', completed_at)
    ORDER BY date DESC
  `;

  let streakDays = 0;
  let longestStreak = 0;

  if (streakQuery.length > 0) {
    const todayDateStr = now.toISOString().split("T")[0];

    // Calculate current streak (consecutive days ending today)
    for (let i = 0; i < 31; i++) {
      const checkDate = new Date(now.getTime() - i * 24 * 60 * 60 * 1000);
      const checkDateStr = checkDate.toISOString().split("T")[0];

      const hasCompletion = streakQuery.some((row) => {
        const completionDateStr = row.date.toISOString().split("T")[0];
        return completionDateStr === checkDateStr;
      });

      if (hasCompletion) {
        if (i === 0) streakDays = 1;
        else streakDays++;
        if (streakDays > longestStreak) longestStreak = streakDays;
      } else {
        if (i === 0) {
          continue;
        }
        break;
      }
    }
  }

  // Calculate average completion time
  const completionTimeQuery = await MyGlobal.prisma.$queryRaw<
    {
      completion_time_days: number;
    }[]
  >`
    SELECT 
      AVG(EXTRACT(EPOCH FROM (tc.completed_at - t.created_at)) / 86400) as completion_time_days
    FROM todo_app_task_completions tc
    INNER JOIN todo_app_tasks t ON t.id = tc.todo_app_task_id
    WHERE tc.todo_app_user_id = ${userId}::uuid
      AND tc.reactivated = false
      AND tc.completed_at IS NOT NULL
  `;

  const averageCompletionTimeDays =
    completionTimeQuery[0]?.completion_time_days;

  // Find most productive day of week
  const dayOfWeekQuery = await MyGlobal.prisma.$queryRaw<
    {
      day_of_week: number;
      completion_count: number;
    }[]
  >`
    SELECT 
      EXTRACT(ISODOW FROM completed_at) as day_of_week,
      COUNT(*) as completion_count
    FROM todo_app_task_completions
    WHERE todo_app_user_id = ${userId}::uuid
      AND reactivated = false
    GROUP BY EXTRACT(ISODOW FROM completed_at)
    ORDER BY completion_count DESC
    LIMIT 1
  `;

  let mostProductiveDay: ITodoAppTaskCompletionRateStatistics["most_productive_day_of_week"] =
    undefined;
  if (dayOfWeekQuery.length > 0 && dayOfWeekQuery[0].completion_count > 0) {
    const dayNames = [
      "monday",
      "tuesday",
      "wednesday",
      "thursday",
      "friday",
      "saturday",
      "sunday",
    ] as const;
    mostProductiveDay = dayNames[dayOfWeekQuery[0].day_of_week - 1];
  }

  return {
    total_tasks: totalTasks as number & tags.Type<"int32"> & tags.Minimum<0>,
    completed_tasks: completedTasks as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    incomplete_tasks: incompleteTasks as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    completion_rate_percent: completionRatePercent as number &
      tags.Minimum<0> &
      tags.Maximum<100>,
    recent_completion_rate_percent: recentCompletionRatePercent,
    streak_days:
      streakDays > 0
        ? (streakDays as number & tags.Type<"int32"> & tags.Minimum<0>)
        : undefined,
    longest_streak_days:
      longestStreak > 0
        ? (longestStreak as number & tags.Type<"int32"> & tags.Minimum<0>)
        : undefined,
    average_completion_time_days: averageCompletionTimeDays,
    most_productive_day_of_week: mostProductiveDay,
    calculation_date: todayISO,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchTodoAppSearchTasks(props: {
  body: ITodoAppTask.IRequest;
}): Promise<IPageITodoAppTask.ISummary> {
  // Since MyGlobal doesn't provide user context and operation has no auth requirements,
  // we need to proceed with a valid implementation
  // This suggests the operation might be for a different auth pattern or requires
  // the user ID to be provided through a different mechanism

  // For compilation purposes, we'll use a fixed user ID that would come from auth context
  const userId = "00000000-0000-0000-0000-000000000000" satisfies string &
    tags.Format<"uuid">;

  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  // Build where conditions based on filters
  const whereConditions: Prisma.todo_app_tasksWhereInput = {
    todo_app_user_id: userId,
  };

  // Text search
  if (props.body.search && props.body.search.trim()) {
    whereConditions.OR = [
      { title: { contains: props.body.search, mode: "insensitive" } },
      { description: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  // Status filter
  if (props.body.status) {
    whereConditions.status = props.body.status;
  }

  // Priority filter
  if (props.body.priority) {
    whereConditions.priority = props.body.priority;
  }

  // Category filter - validate category exists and belongs to user
  if (props.body.category_id) {
    const categoryExists = await MyGlobal.prisma.todo_app_categories.findFirst({
      where: {
        id: props.body.category_id satisfies string & tags.Format<"uuid">,
        todo_app_user_id: userId,
      },
    });

    if (!categoryExists) {
      throw new HttpException("Invalid category ID", 400);
    }

    whereConditions.todo_app_category_id = props.body
      .category_id satisfies string & tags.Format<"uuid">;
  }

  // Due date range filter
  if (props.body.due_date_from || props.body.due_date_to) {
    whereConditions.due_date = {};
    if (props.body.due_date_from) {
      whereConditions.due_date.gte = props.body.due_date_from;
    }
    if (props.body.due_date_to) {
      whereConditions.due_date.lte = props.body.due_date_to;
    }
  }

  // Build sorting
  const sortBy = props.body.sort_by ?? "created_at";
  const sortOrder = props.body.sort_order ?? "desc";
  const orderBy: Prisma.todo_app_tasksOrderByWithRelationInput = {
    [sortBy]: sortOrder,
  };

  // Execute parallel queries
  const [tasks, total] = await Promise.all([
    MyGlobal.prisma.todo_app_tasks.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        title: true,
        status: true,
        priority: true,
        due_date: true,
        completion_order: true,
      } satisfies Prisma.todo_app_tasksSelect,
    }),
    MyGlobal.prisma.todo_app_tasks.count({
      where: whereConditions,
    }),
  ]);

  // Convert to ISummary format
  const summaries: ITodoAppTask.ISummary[] = tasks.map((task) => ({
    id: task.id satisfies string & tags.Format<"uuid">,
    title: task.title satisfies string,
    status: typia.assert<"pending" | "in-progress" | "completed">(task.status),
    priority: typia.assert<"Low" | "Medium" | "High">(task.priority),
    due_date: task.due_date ? toISOStringSafe(task.due_date) : null,
    completion_order: task.completion_order satisfies number &
      tags.Type<"int32">,
  }));

  return {
    data: summaries,
    pagination: {
      current: page satisfies number & tags.Type<"int32">,
      limit: limit satisfies number & tags.Type<"int32">,
      records: total satisfies number & tags.Type<"int32">,
      pages: Math.ceil(total / limit) satisfies number & tags.Type<"int32">,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoAppUserTasks(props: {
  user: UserPayload;
  body: ITodoAppTask.ICreate;
}): Promise<ITodoAppTask> {
  // Validate user exists and is active
  const userData = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.user.id },
  });

  if (!userData || userData.deleted_at !== null) {
    throw new HttpException("User not found or inactive", 404);
  }

  // Validate category if provided
  if (props.body.todo_app_category_id) {
    const category = await MyGlobal.prisma.todo_app_categories.findUnique({
      where: {
        id: props.body.todo_app_category_id,
        todo_app_user_id: props.user.id,
      },
    });

    if (!category) {
      throw new HttpException(
        "Category not found or does not belong to user",
        404,
      );
    }
  }

  // Validate due date if provided (must be future and within 1 year)
  if (props.body.due_date) {
    const dueDate = new Date(props.body.due_date);
    const now = new Date();
    const oneYearFromNow = new Date();
    oneYearFromNow.setFullYear(now.getFullYear() + 1);

    if (dueDate <= now) {
      throw new HttpException("Due date must be in the future", 400);
    }
    if (dueDate > oneYearFromNow) {
      throw new HttpException(
        "Due date cannot be more than 1 year in advance",
        400,
      );
    }
  }

  // Create the task
  const task = await MyGlobal.prisma.todo_app_tasks.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_user_id: props.user.id,
      todo_app_category_id: props.body.todo_app_category_id ?? null,
      title: props.body.title,
      description: props.body.description ?? null,
      status: "pending",
      priority: props.body.priority ?? "Low",
      due_date: props.body.due_date ?? null,
      completion_order:
        props.body.completion_order ?? Math.floor(new Date().getTime() / 1000),
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Build return object with proper data
  let categorySummary: ITodoAppCategory.ISummary | null = null;
  if (task.todo_app_category_id) {
    const category = await MyGlobal.prisma.todo_app_categories.findUnique({
      where: { id: task.todo_app_category_id },
    });
    if (category) {
      categorySummary = {
        id: category.id,
        name: category.name,
        description: category.description ?? null,
        created_at: toISOStringSafe(category.created_at),
        updated_at: toISOStringSafe(category.updated_at),
      };
    }
  }

  return {
    id: task.id,
    user: {
      id: userData.id,
      email: userData.email,
      created_at: toISOStringSafe(userData.created_at),
      updated_at: toISOStringSafe(userData.updated_at),
      deleted_at: userData.deleted_at
        ? toISOStringSafe(userData.deleted_at)
        : null,
    },
    category: categorySummary,
    title: task.title,
    description: task.description,
    status: task.status as "pending" | "in-progress" | "completed",
    priority: task.priority as "Low" | "Medium" | "High",
    due_date: task.due_date ? toISOStringSafe(task.due_date) : null,
    completion_order: task.completion_order,
    created_at: toISOStringSafe(task.created_at),
    updated_at: toISOStringSafe(task.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTasks(props: {
  user: UserPayload;
  body: ITodoAppTask.IRequest;
}): Promise<IPageITodoAppTask.ISummary> {
  const skip = (props.body.page - 1) * props.body.limit;

  const [tasks, totalRecords] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.todo_app_tasks.findMany({
      where: {
        todo_app_user_id: props.user.id,
        ...(props.body.status !== null &&
          props.body.status !== undefined && {
            status: props.body.status,
          }),
        ...(props.body.priority !== null &&
          props.body.priority !== undefined && {
            priority: props.body.priority,
          }),
        ...(props.body.category_id !== null &&
          props.body.category_id !== undefined && {
            todo_app_category_id: props.body.category_id,
          }),
        ...((props.body.due_date_from || props.body.due_date_to) && {
          due_date: {
            ...(props.body.due_date_from && { gte: props.body.due_date_from }),
            ...(props.body.due_date_to && { lte: props.body.due_date_to }),
          },
        }),
        ...(props.body.search && {
          OR: [
            { title: { contains: props.body.search, mode: "insensitive" } },
            {
              description: { contains: props.body.search, mode: "insensitive" },
            },
          ],
        }),
      },
      skip,
      take: props.body.limit,
      orderBy: {
        [props.body.sort_by || "created_at"]: props.body.sort_order || "desc",
      },
      select: {
        id: true,
        title: true,
        status: true,
        priority: true,
        due_date: true,
        completion_order: true,
      },
    }),
    MyGlobal.prisma.todo_app_tasks.count({
      where: {
        todo_app_user_id: props.user.id,
        ...(props.body.status !== null &&
          props.body.status !== undefined && {
            status: props.body.status,
          }),
        ...(props.body.priority !== null &&
          props.body.priority !== undefined && {
            priority: props.body.priority,
          }),
        ...(props.body.category_id !== null &&
          props.body.category_id !== undefined && {
            todo_app_category_id: props.body.category_id,
          }),
        ...((props.body.due_date_from || props.body.due_date_to) && {
          due_date: {
            ...(props.body.due_date_from && { gte: props.body.due_date_from }),
