import { ITodoAppCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCategory";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoAppUserTasksTaskId(props: {
  user: UserPayload;
  taskId: string & tags.Format<"uuid">;
  body: ITodoAppTask.IUpdate;
}): Promise<ITodoAppTask> {
  // Verify task exists and belongs to user
  const existingTask = await MyGlobal.prisma.todo_app_tasks.findUnique({
    where: { id: props.taskId },
  });

  if (!existingTask) {
    throw new HttpException("Task not found", 404);
  }

  if (existingTask.todo_app_user_id !== props.user.id) {
    throw new HttpException(
      "You do not have permission to update this task",
      403,
    );
  }

  // Build update data with proper handling for nullable fields
  const updateData: any = {
    updated_at: new Date(),
  };

  if (props.body.title !== undefined) {
    updateData.title = props.body.title;
  }
  if (props.body.description !== undefined) {
    updateData.description = props.body.description;
  }
  if (props.body.todo_app_category_id !== undefined) {
    updateData.todo_app_category_id = props.body.todo_app_category_id;
  }
  if (props.body.status !== undefined) {
    updateData.status = props.body.status;
  }
  if (props.body.priority !== undefined) {
    updateData.priority = props.body.priority;
  }
  if (props.body.due_date !== undefined) {
    updateData.due_date = props.body.due_date;
  }
  if (props.body.completion_order !== undefined) {
    updateData.completion_order = props.body.completion_order;
  }

  // Build update data inline with proper type safety
  const updatedTask = await MyGlobal.prisma.todo_app_tasks.update({
    where: { id: props.taskId },
    data: updateData,
  });

  // Load category information if task has a category
  let categoryInfo: ITodoAppCategory.ISummary | null = null;
  if (updatedTask.todo_app_category_id !== null) {
    const category = await MyGlobal.prisma.todo_app_categories.findUnique({
      where: { id: updatedTask.todo_app_category_id },
      select: {
        id: true,
        name: true,
        description: true,
        created_at: true,
        updated_at: true,
      },
    });

    if (category) {
      categoryInfo = {
        id: category.id,
        name: category.name,
        description: category.description,
        created_at: toISOStringSafe(category.created_at),
        updated_at: toISOStringSafe(category.updated_at),
      };
    }
  }

  // Get user info from database since UserPayload doesn't have email
  const user = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.user.id },
    select: {
      id: true,
      email: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!user) {
    throw new HttpException("User not found", 404);
  }

  // Return the updated task
  return {
    id: updatedTask.id,
    user: {
      id: user.id,
      email: user.email,
      created_at: toISOStringSafe(user.created_at),
      updated_at: toISOStringSafe(user.updated_at),
      deleted_at: user.deleted_at
        ? toISOStringSafe(user.deleted_at)
        : undefined,
    },
    category: categoryInfo,
    title: updatedTask.title,
    description: updatedTask.description,
    status: typia.assert<"pending" | "in-progress" | "completed">(
      updatedTask.status,
    ),
    priority: typia.assert<"Low" | "Medium" | "High">(updatedTask.priority),
    due_date: updatedTask.due_date
      ? toISOStringSafe(updatedTask.due_date)
      : null,
    completion_order: updatedTask.completion_order,
    created_at: toISOStringSafe(updatedTask.created_at),
    updated_at: toISOStringSafe(updatedTask.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoAppUser.IRefresh;
}): Promise<ITodoAppUser.IAuthorized> {
  // 1. Verify and decode the refresh token
  let decoded: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "user";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string & tags.Format<"uuid">;
      session_id: string & tags.Format<"uuid">;
      type: "user";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // 2. Validate type matches expected user type
  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  // 3. Validate session exists and is active
  const session = await MyGlobal.prisma.todo_app_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      user_id: decoded.id,
    },
    include: {
      user: true,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // 4. Check if user account is deleted
  if (session.user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // 5. Generate new access and refresh tokens with same session_id
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id, // Reuse same session_id
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id, // Reuse same session_id
      tokenType: "refresh",
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // 6. Update session expiration time
  await MyGlobal.prisma.todo_app_user_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: refreshExpires,
    },
  });

  // 7. Return user info with new tokens
  return {
    id: session.user.id,
    email: session.user.email,
    created_at: toISOStringSafe(session.user.created_at),
    updated_at: session.user.updated_at
      ? toISOStringSafe(session.user.updated_at)
      : undefined,
    deleted_at: session.user.deleted_at
      ? toISOStringSafe(session.user.deleted_at)
      : undefined,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestJoin(props: {
  body: ITodoAppGuest.ICreate;
}): Promise<ITodoAppGuest.IAuthorized> {
  // Generate unique session identifier for guest tracking
  const sessionIdentifier = `guest_${v4()}` as string;

  // Check for duplicate session identifier (extremely rare but possible)
  const existing = await MyGlobal.prisma.todo_app_guests.findFirst({
    where: { session_identifier: sessionIdentifier },
  });

  if (existing) {
    throw new HttpException("Session identifier collision", 400);
  }

  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  // Create guest actor record first (primary table)
  const guest = await MyGlobal.prisma.todo_app_guests.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      session_identifier: sessionIdentifier,
      created_at: now,
      updated_at: now,
      expired_at: refreshExpires,
    },
  });

  // Create guest session record (subsidiary table)
  const session = await MyGlobal.prisma.todo_app_guest_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      guest_id: guest.id,
      ip: props.body.ip ?? "0.0.0.0",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens with guest payload
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return complete guest authorization response
  return {
    id: guest.id,
    session_identifier: guest.session_identifier,
    created_at: toISOStringSafe(guest.created_at),
    updated_at: toISOStringSafe(guest.updated_at),
    expired_at: guest.expired_at
      ? toISOStringSafe(guest.expired_at)
      : undefined,
    token,
  };
}

