export async function patchTodoAppUserCategoriesCategoryIdTasks(props: {
  user: UserPayload;
  categoryId: string & tags.Format<"uuid">;
  body: ITodoAppTask.IRequest;
}): Promise<IPageITodoAppTask.ISummary> {
  // Validate that the category exists and belongs to the current user
  const category = await MyGlobal.prisma.todo_app_categories.findUnique({
    where: {
      id: props.categoryId,
      todo_app_user_id: props.user.id,
    },
  });

  if (!category) {
    throw new HttpException("Category not found or access denied", 404);
  }

  // Extract pagination parameters
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Build where conditions for filtering
  const whereConditions: Prisma.todo_app_tasksWhereInput = {
    todo_app_user_id: props.user.id,
    todo_app_category_id: props.categoryId,
    // Verify body category_id matches path categoryId if both are provided
    ...(props.body.category_id && props.body.category_id !== props.categoryId
      ? { todo_app_category_id: null } // Return empty results if mismatch
      : {}),
  };

  // Add status filter
  if (props.body.status) {
    whereConditions.status = props.body.status;
  }

  // Add priority filter
  if (props.body.priority) {
    whereConditions.priority = props.body.priority;
  }

  // Add due date range filter
  if (props.body.due_date_from || props.body.due_date_to) {
    whereConditions.due_date = {};
    if (props.body.due_date_from) {
      whereConditions.due_date.gte = props.body.due_date_from;
    }
    if (props.body.due_date_to) {
      whereConditions.due_date.lte = props.body.due_date_to;
    }
  }

  // Add search filter if provided
  if (props.body.search) {
    whereConditions.OR = [
      { title: { contains: props.body.search, mode: "insensitive" } },
      { description: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  // Build order by condition
  const orderBy: Prisma.todo_app_tasksOrderByWithRelationInput = {};
  if (props.body.sort_by) {
    orderBy[props.body.sort_by] = props.body.sort_order ?? "desc";
  } else {
    orderBy.created_at = "desc"; // Default sort by creation date descending
  }

  // Execute queries with pagination
  const [tasks, total] = await Promise.all([
    MyGlobal.prisma.todo_app_tasks.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.todo_app_tasks.count({ where: whereConditions }),
  ]);

  // Map results to response format with proper null/undefined handling
  const data = tasks.map(
    (task): ITodoAppTask.ISummary => ({
      id: task.id as string & tags.Format<"uuid">,
      title: task.title,
      status: task.status as "pending" | "in-progress" | "completed",
      priority: task.priority as "Low" | "Medium" | "High",
      due_date: task.due_date ? toISOStringSafe(task.due_date) : undefined,
      completion_order: task.completion_order,
    }),
  );

  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskCompletionsStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionsStatistics";
import { IDailyCompletionEntry } from "@ORGANIZATION/PROJECT-api/lib/structures/IDailyCompletionEntry";
import { ICompletionTrend } from "@ORGANIZATION/PROJECT-api/lib/structures/ICompletionTrend";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserStatisticsDailyCompletions(props: {
  user: UserPayload;
}): Promise<ITodoAppTaskCompletionsStatistics> {
  // Get all completion records for the authenticated user
  const completions = await MyGlobal.prisma.todo_app_task_completions.findMany({
    where: {
      todo_app_user_id: props.user.id,
      reactivated: false, // Only count final completions, not ones that were later reactivated
    },
    orderBy: {
      completed_at: "asc",
    },
  });

  // Group completions by calendar date
  const dailyMap = new Map<string, number>();

  for (const completion of completions) {
    // Extract date part (YYYY-MM-DD format) from completed_at datetime
    // toISOStringSafe returns ISO string format, split to get date part
    const dateOnly = toISOStringSafe(completion.completed_at).split("T")[0];
    dailyMap.set(dateOnly, (dailyMap.get(dateOnly) || 0) + 1);
  }

  // Convert to array of daily entries and sort by date
  const dailyCompletions: IDailyCompletionEntry[] = Array.from(
    dailyMap.entries(),
  )
    .map(([date, completion_count]) => ({
      date: date as string & tags.Format<"date">,
      completion_count: completion_count as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
    }))
    .sort((a, b) => a.date.localeCompare(b.date));

  // Calculate total completions
  const total_completions = completions.length as number &
    tags.Type<"int32"> &
    tags.Minimum<0>;

  // Calculate distinct days with completions
  const distinct_days_with_completions = dailyMap.size as number &
    tags.Type<"int32"> &
    tags.Minimum<0> &
    tags.Maximum<31>;

  // Calculate average daily completions (optional field)
  const average_daily_completions =
    distinct_days_with_completions > 0
      ? total_completions / distinct_days_with_completions
      : undefined;

  // Find best day (most completions)
  let best_day_completions: number | undefined;
  let best_day_date: string | undefined;

  for (const [date, count] of dailyMap.entries()) {
    if (!best_day_completions || count > best_day_completions) {
      best_day_completions = count as number &
        tags.Type<"int32"> &
        tags.Minimum<0>;
      best_day_date = date as string & tags.Format<"date">;
    }
  }

  // Calculate trend analysis (optional)
  let trend: ICompletionTrend | undefined;

  if (dailyCompletions.length >= 14) {
    // Get last 14 days split into recent week and previous week
    const recentWeek = dailyCompletions.slice(-7);
    const previousWeek = dailyCompletions.slice(-14, -7);

    const recentAvg =
      recentWeek.reduce((sum, day) => sum + day.completion_count, 0) / 7;
    const previousAvg =
      previousWeek.reduce((sum, day) => sum + day.completion_count, 0) / 7;

    let direction: "increasing" | "decreasing" | "stable";
    let weekly_average_change_percent: number | undefined;

    if (previousAvg > 0) {
      weekly_average_change_percent =
        ((recentAvg - previousAvg) / previousAvg) * 100;

      if (Math.abs(weekly_average_change_percent) < 5) {
        direction = "stable";
      } else if (weekly_average_change_percent > 0) {
        direction = "increasing";
      } else {
        direction = "decreasing";
      }
    } else {
      direction = recentAvg > 0 ? "increasing" : "stable";
      weekly_average_change_percent =
        previousAvg === 0 && recentAvg > 0 ? 100 : 0;
    }

    // Calculate consistency score (based on coefficient of variation)
    const allCounts = dailyCompletions.map((d) => d.completion_count);
    const avg =
      allCounts.reduce((sum, count) => sum + count, 0) / allCounts.length;
    const variance =
      allCounts.reduce((sum, count) => sum + Math.pow(count - avg, 2), 0) /
      allCounts.length;
    const stdDev = Math.sqrt(variance);
    const coefficientOfVariation = avg > 0 ? stdDev / avg : 0;
    const consistency_score = Math.max(
      0,
      Math.min(100, (1 - coefficientOfVariation) * 100),
    );

    trend = {
      direction,
      weekly_average_change_percent,
      consistency_score,
    };
  }

  // Determine analysis period (optional)
  let analysis_period_start_date: string | undefined;
  let analysis_period_end_date: string | undefined;

  if (dailyCompletions.length > 0) {
    analysis_period_start_date = dailyCompletions[0].date;
    analysis_period_end_date =
      dailyCompletions[dailyCompletions.length - 1].date;
  }

  return {
    total_completions,
    distinct_days_with_completions,
    daily_completions: dailyCompletions,
    average_daily_completions,
    best_day_completions,
    best_day_date,
    trend,
    analysis_period_start_date,
    analysis_period_end_date,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskCompletion } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletion";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTasksBulkComplete(props: {
  user: UserPayload;
  body: ITodoAppTaskCompletion.ICreate;
}): Promise<ITodoAppTaskCompletion.ISummary> {
  const startTime = Date.now();
  const currentTime = toISOStringSafe(new Date());

  // Fetch all tasks and validate ownership
  const tasks = await MyGlobal.prisma.todo_app_tasks.findMany({
    where: {
      id: { in: props.body.task_ids },
      todo_app_user_id: props.user.id,
    },
  });

  // Check if all requested tasks exist and belong to user
  if (tasks.length !== props.body.task_ids.length) {
    throw new HttpException(
      "Some tasks not found or don't belong to user",
      404,
    );
  }

  // Categorize tasks by status
  const completableTasks = tasks.filter(
    (task) => task.status === "pending" || task.status === "in-progress",
  );
  const alreadyCompletedTasks = tasks.filter(
    (task) => task.status === "completed",
  );

  const successfullyCompleted: string[] = [];
  const failedTaskIds: string[] = [];

  // Use transaction for atomic bulk operations
  try {
    await MyGlobal.prisma.$transaction(async (tx) => {
      for (const task of completableTasks) {
        try {
          // Update task status to completed
          await tx.todo_app_tasks.update({
            where: { id: task.id },
            data: {
              status: "completed",
              updated_at: currentTime,
            },
          });

          // Create completion record
          const completionRecord = await tx.todo_app_task_completions.create({
            data: {
              id: v4() as string & tags.Format<"uuid">,
              todo_app_task_id: task.id,
              todo_app_user_id: props.user.id,
              completed_at: currentTime,
              completion_order: task.completion_order,
              reactivated: false,
              created_at: currentTime,
            },
          });

          successfullyCompleted.push(task.id);
        } catch (error) {
          // Track failed tasks but continue processing
          failedTaskIds.push(task.id);
        }
      }
    });
  } catch (transactionError) {
    // If transaction fails completely, all tasks are considered failed
    throw new HttpException("Bulk completion operation failed", 500);
  }

  const processingTime = Date.now() - startTime;

  // Generate appropriate message based on results
  let message = "";
  if (failedTaskIds.length > 0) {
    message = `${successfullyCompleted.length} tasks completed successfully, ${failedTaskIds.length} failed to complete.`;
  } else if (alreadyCompletedTasks.length > 0) {
    message = `${successfullyCompleted.length} tasks completed successfully. ${alreadyCompletedTasks.length} tasks were already completed.`;
  } else {
    message = `Successfully completed ${successfullyCompleted.length} tasks.`;
  }

  return {
    total_requested: props.body.task_ids.length,
    successfully_completed: successfullyCompleted.length,
    failed_count: failedTaskIds.length,
    skipped_count: alreadyCompletedTasks.length,
    completion_percentage:
      (successfullyCompleted.length / props.body.task_ids.length) * 100,
    completed_task_ids: successfullyCompleted as (string &
      tags.Format<"uuid">)[],
    failed_task_ids: failedTaskIds as (string & tags.Format<"uuid">)[],
    message,
    processing_time_ms: processingTime,
    timestamp: currentTime,
  };
}

